  if (/\b(?:christmas|xmas)\b/.test(t)) return 'christmas';
  if (/\bthanksgiving\b/.test(t)) return 'thanksgiving';
  if (/\beaster\b/.test(t)) return 'easter';
  if (/\bvalentines?\b/.test(t)) return 'valentine';
