// events with Field of Screams first).
const SEARCH_EVENT_RANK_SKIP = new Set(['event', 'events', 'in', 'at', 'the', 'a', 'an', 'and', 'of', 'on', 'for', 'to', 'near', 'this', 'next', 'what', 'whats', 's', 'things', 'do', 'okanagan', 'bc']);
