function renderDestinationsPage(entries = destinationRegionEntries()) {
  const title = 'Okanagan Destinations | Okanagan Roam';
  const description = 'Pick an Okanagan destination, from Enderby to Osoyoos and the ski hills, and find its restaurants, wineries, beaches and events.';
  const canonical = 'https://okanaganroam.com/destinations';
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: 'Destinations', url: canonical },
  ]);
  const geo = (r) => { const i = DESTINATION_GEO_ORDER.indexOf(r.region); return i < 0 ? 999 : i; };
  const ordered = entries.map((g) => ({ ...g, regions: g.regions.slice().sort((a, b) => geo(a) - geo(b)) }));
  const listed = new Set(ordered.flatMap((g) => g.regions.map((r) => r.region)));
  // Summary-page lists (SEO audit 2, 2026-10-17): each entry is position, url and name. A partial item object
  // (a business with only a name) mixed both of Google's list formats and failed its required fields.
  const itemList = {
    '@context': 'https://schema.org',
    '@type': 'ItemList',
    name: 'Okanagan destinations',
    itemListElement: ordered.flatMap((g) => g.regions).map((r, i) => ({ '@type': 'ListItem', position: i + 1, url: `https://okanaganroam.com/${r.region}`, name: `${r.label}, BC` })),
  };
  const starts = DESTINATION_STARTS.filter((x) => listed.has(x.region));
  const startsHtml = starts.length ? `<section class="destination-starts" aria-labelledby="destinationStartsHeading">
    <h2 id="destinationStartsHeading">Not sure where to start?</h2>
    <ul>
${starts.map((x) => `      <li><strong>${escapeHtml(x.label)}</strong><a href="/${x.region}">${escapeHtml(REGION_LABELS[x.region])}</a> &mdash; ${escapeHtml(x.why)}</li>`).join('\n')}
    </ul>
  </section>` : '';
  const sections = ordered.map((g) => `<h2 class="category-subsection-heading">${escapeHtml(g.label)}</h2>
  <ul class="card-grid destination-photo-grid">
    ${g.regions.map((r) => {
      const photo = destinationCardPhoto(r.region);
      return `
      <li class="category-card">
        <h3 class="destination-card-title"><a href="/${r.region}">${escapeHtml(r.label)}</a></h3>${DESTINATION_TAGLINES[r.region] ? `
        <p class="destination-tagline">${escapeHtml(DESTINATION_TAGLINES[r.region])}</p>` : ''}
        <p class="venue-meta">${r.venues} place${r.venues === 1 ? '' : 's'} to eat, drink and explore</p>${photo ? `
        <div class="destination-card-photo${photo.map ? ' destination-card-map' : ''}"><img src="${photo.src}"${tileSrcsetAttrs(photo.src, DESTINATION_TILE_SIZES)} alt="" width="800" height="533" loading="lazy" decoding="async"></div>` : ''}
      </li>`;
    }).join('\n')}
  </ul>`).join('\n  ');
  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(title, description, canonical, [breadcrumb, itemList], { shareImage: '/images/okanagan-valley-sunset-hero.webp', golfTheme: true })}
${renderOutdoorThemeStyles()}
${DESTINATION_PHOTO_GRID_STYLE}
${DESTINATION_PAGE_EXTRA_STYLE}
${golfEngagementHeadHtml('fd', true, 'hub')}
</head>
<body class="golf-page outdoor-page region-page destinations-page">
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main" id="main">
  ${breadcrumbNavHtml([
    { name: 'Home', href: '/' },
    { name: 'Destinations' },
  ])}
  <h1>Choose Your Okanagan Destination</h1>
  <p class="subtitle">Every destination on Okanagan Roam, from Enderby to Osoyoos and the ski resorts. Pick one to see its restaurants, wineries, beaches, outdoor places, events and more.</p>
  ${startsHtml}
  ${sections}
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
</body>
</html>`;
}

// ---------- Map page (Stage 3.4, 2026-09-29): /map ----------
// Every "Map" control (the header's Discover -> Map, the homepage's Build
// Your Trip map graphic) used to send visitors to /browse?openMap=1, where
// the map opened below the fold with its only open/close control hidden.
// /map shows the same map the directory had -- one pin per town/area
// centre, the same coordinates, each pin listing that area's places -- on
// screen straight away, with a visible "Close map" control, in the site's
// own header/footer/map styles. Pins mark areas, not addresses; every place
// links to its own page (whose "View on map" opens Google Maps as before).
// Read-only: names, types, regions and slugs as stored.
const MAP_AREA_CENTERS = {
  kelowna: [49.8880, -119.4960], 'west-kelowna': [49.8622, -119.6516], peachland: [49.7719, -119.7386],
  naramata: [49.5978, -119.5850], penticton: [49.4991, -119.5937], 'okanagan-falls': [49.3512, -119.5568],
  summerland: [49.6011, -119.6773], oliver: [49.1822, -119.5502], osoyoos: [49.0328, -119.4692],
  vernon: [50.2670, -119.2720], 'big-white': [49.7218, -118.9288], silverstar: [50.3599, -119.0588],
  apex: [49.3910, -119.9040], baldy: [49.1528, -119.2364], 'lake-country': [50.0680, -119.4090],
  coldstream: [50.2260, -119.2010], lumby: [50.2483, -118.9722], armstrong: [50.4489, -119.1997],
  enderby: [50.5487, -119.1400], kaleden: [49.3940, -119.6010],
};
const MAP_POPUP_LIMIT = 12;
function mapAreaPins() {
  const rows = db.prepare('SELECT name, region, type, slug FROM venues WHERE redirect_to IS NULL AND slug IS NOT NULL').all()
    .filter((v) => REGION_LABELS[v.region] && CATEGORY_SLUGS[v.type]);
  return VALID_REGIONS.filter((r) => MAP_AREA_CENTERS[r]).map((region) => {
    const places = rows.filter((v) => v.region === region).sort((a, b) => String(a.name).localeCompare(String(b.name)));
    const label = REGION_LABELS[region];
    const list = places.slice(0, MAP_POPUP_LIMIT).map((v) => `<li><a href="/${v.region}/${CATEGORY_SLUGS[v.type]}/${escapeHtml(v.slug)}">${escapeHtml(v.name)}</a>, ${escapeHtml(CATEGORY_LABELS[v.type].singular)}</li>`).join('');
    const regionPage = Object.keys(getRegionCategoryCounts(region)).length > 0;
    const popup = `<h4>${escapeHtml(label)} &middot; ${places.length} ${places.length === 1 ? 'place' : 'places'}</h4>`
      + (places.length ? `<ul class="map-popup-list">${list}</ul>` : '<p class="map-popup-more">No places listed here yet.</p>')
      + (regionPage ? `<div class="map-popup-more"><a href="/${region}">See everything in ${escapeHtml(label)} &rarr;</a></div>` : '');
    return { region, center: MAP_AREA_CENTERS[region], count: places.length, popup };
  });
}
// ---------- Places map (2026-10-14): /map ----------
// One pin per place that has a map position (about 1,700 of 1,774), grouped
// into numbered clusters that open as you zoom, with category chips, a name
// search and a town picker. Each pin's popup names the place, its kind and
// town, and links to its page. Replaces the ~20 town-centre pins (each capped
// at 12 places) and the "Close map" button.
const MAP_GROUPS = [
  { key: 'food', label: 'Food & Drink', types: ['restaurant', 'cafe', 'pub', 'cocktail', 'brewery', 'distillery'] },
  { key: 'wine', label: 'Wineries', types: ['winery'] },
  { key: 'beach', label: 'Beaches', types: ['beach'] },
  { key: 'outdoor', label: 'Outdoors', types: ['outdoor'] },
  { key: 'golf', label: 'Golf', types: ['golf'] },
  { key: 'do', label: 'Tours, sports & indoor', types: ['tour', 'sport', 'indoor'] },
];
const MAP_GROUP_BY_TYPE = Object.fromEntries(MAP_GROUPS.flatMap((g) => g.types.map((t) => [t, g.key])));
function mapPlaces() {
  return db.prepare('SELECT id, name, region, type, slug, latitude, longitude FROM venues WHERE redirect_to IS NULL AND slug IS NOT NULL AND latitude IS NOT NULL AND longitude IS NOT NULL').all()
    .filter((v) => REGION_LABELS[v.region] && CATEGORY_SLUGS[v.type] && MAP_GROUP_BY_TYPE[v.type] && Number.isFinite(Number(v.latitude)) && Number.isFinite(Number(v.longitude)));
}
