const FD_NOODLE_RE = /\b(?:ramen|pho|noodles?|udon)\b/i;
// The key of a card's example photo: "<type>-<n>", "<type>-dog" or "noodle".
// Keys (not URLs) go on the card so 934 cards do not repeat long paths; the
// stylesheet maps each key to its photo once.
function foodDrinkCardPhotoKey(v) {
  const t = FD_CARD_PHOTOS[v.type] ? v.type : 'restaurant';
  if (t === 'restaurant' && FD_NOODLE_RE.test(`${v.cuisine || ''} ${v.name || ''}`)) return 'noodle';
  const list = FD_CARD_PHOTOS[t];
  const id = Number(v.id) || 0;
  // About one dog-friendly card in three shows the dog photo, so a run of
  // dog-friendly places does not repeat one picture.
  if (Number(v.dog_friendly) === 1 && FD_CARD_DOG_PHOTOS[t] && id % 3 === 0) return `${t}-dog`;
  return `${t}-${id % list.length}`;
}
// No twin example photos side by side (2026-10-16): the "<type>-<n>" key
// comes from the venue id, so neighbouring cards could land on the same
// picture (two wineries showing the same toast). Given the keys in card
// order, swap a key for another photo of the same kind when it matches one
// of the previous three example-photo cards (covering the card to its left
// and the one above it in a three-column grid). Own photos and single-photo
// kinds are left alone.
const PHOTO_KEY_SPREAD = 3;
function photoKeySpreader() {
  const recent = [];
  return (key) => {
    const m = /^([a-z]+)-(\d+)$/.exec(key);
    const list = m && FD_CARD_PHOTOS[m[1]];
    if (list && list.length > 1 && recent.includes(key)) {
      for (let step = 1; step < list.length; step++) {
        const alt = `${m[1]}-${(Number(m[2]) + step) % list.length}`;
        if (!recent.includes(alt)) { key = alt; break; }
      }
    }
    recent.push(key);
    if (recent.length > PHOTO_KEY_SPREAD) recent.shift();
    return key;
  };
}
function foodDrinkCardPhotoCss() {
  const rules = [];
  // Activity example photos keep their focal height on the short card strip
  // (the camping tent sits low in its photo).
  const y = (t) => (EXAMPLE_ACTIVITY_PHOTOS[t] && EXAMPLE_ACTIVITY_PHOTOS[t].pos !== 50 ? `;--fd-ph-y:${EXAMPLE_ACTIVITY_PHOTOS[t].pos}%` : '');
  for (const [t, list] of Object.entries(FD_CARD_PHOTOS)) list.forEach((src, i) => rules.push(`[data-ph="${t}-${i}"]{--fd-ph:url('${src}')${y(t)}}`));
  for (const [t, src] of Object.entries(FD_CARD_DOG_PHOTOS)) rules.push(`[data-ph="${t}-dog"]{--fd-ph:url('${src}')}`);
  rules.push(`[data-ph="noodle"]{--fd-ph:url('/images/trip-v3/stops/stop-restaurant-noodle-480.jpg')}`);
  return rules.map((r) => `  body.fd-page li.venue-card${r}`).join('\n');
}
const FD_HUB_LABEL_BY_TYPE = Object.fromEntries(FD_HUB_TYPES.map((t) => [t.type, t.label]));
const FD_HUB_LABEL_BY_FEATURE = Object.fromEntries(FD_HUB_FEATURES.map((f) => [f.key, f.label]));

// The hub's universe: every active venue whose PRIMARY type is one of the
// five, plus every venue holding an fd_* secondary membership -- the same
// "effective categories" rule the API already uses, so a brewery that is also
// a restaurant appears once and answers to both chips.
function getFoodDrinkHubVenues() {
  const typePlaceholders = FOOD_DRINK_TYPES.map(() => '?').join(', ');
  const kindPlaceholders = FD_CATEGORY_COLLECTION_KINDS.map(() => '?').join(', ');
  const rows = db.prepare(`
    SELECT v.* FROM venues v
    WHERE v.redirect_to IS NULL AND (
      v.type IN (${typePlaceholders})
      OR EXISTS (
        SELECT 1 FROM collection_items ci
        JOIN collections c ON c.id = ci.collection_id
        WHERE ci.content_type = 'venue' AND ci.content_id = v.id AND c.kind IN (${kindPlaceholders})
      )
    )
    ORDER BY v.name ASC
  `).all(...FOOD_DRINK_TYPES, ...FD_CATEGORY_COLLECTION_KINDS).map(rowToVenue);
  return attachFoodDrinkCategories(rows);
}
// venue id -> effective category list, for the client script's filtering.
function foodDrinkCategoriesByVenue(venues) {
  const map = new Map();
  for (const v of venues) map.set(v.id, (v.fd_categories && v.fd_categories.length) ? v.fd_categories : (FD_CATEGORY_KIND_BY_TYPE[v.type] ? [v.type] : []));
  return map;
}
// venue id -> the feature keys that venue actually has set.
function foodDrinkFeaturesByVenue(venues) {
  const map = new Map();
  for (const v of venues) map.set(v.id, FD_HUB_FEATURES.filter((f) => Number(v[f.key]) === 1).map((f) => f.key));
  return map;
}

// The filter predicate, shared verbatim by the server render and the inline
// client script (see FD_HUB_FILTER_CLIENT_PREDICATE_SRC). Types OR, regions
// OR, features AND, and AND between the three groups; an empty group imposes
// no constraint. This is Food & Drink's OWN predicate -- the Outdoors/What's
// On one is untouched, because their semantics differ (no feature group).
function foodDrinkFilterMatches(selTypes, selFeatures, selRegions, venueCats, venueFeatures, venueRegion) {
  const typeOk = !selTypes.length || selTypes.some((t) => venueCats.includes(t));
  const regionOk = !selRegions.length || selRegions.includes(venueRegion);
  const featureOk = selFeatures.every((f) => venueFeatures.includes(f));
  return typeOk && regionOk && featureOk;
}
const FD_HUB_FILTER_CLIENT_PREDICATE_SRC = `function fdMatches(types, features, regions, venueCats, venueFeatures, venueRegion){
    var typeOk = !types.length, regionOk = !regions.length || regions.indexOf(venueRegion) !== -1;
    for (var i = 0; i < types.length && !typeOk; i++) { if (venueCats.indexOf(types[i]) !== -1) typeOk = true; }
    var featureOk = true;
    for (var j = 0; j < features.length && featureOk; j++) { if (venueFeatures.indexOf(features[j]) === -1) featureOk = false; }
    return typeOk && regionOk && featureOk;
  }`;
function filterFoodDrinkVenues(venues, f, catsById, featsById) {
  return venues.filter((v) => foodDrinkFilterMatches(f.types, f.features, f.regions, catsById.get(v.id) || [], featsById.get(v.id) || [], v.region));
}
// ?types=a,b&features=x,y&regions=c,d -- unknown values are dropped and
// duplicates collapse, so a hand-edited link degrades to "fewer constraints",
// never an error page. Anything else in the query is ignored.
function parseFoodDrinkFilterQuery(query) {
  const split = (v) => (typeof v === 'string' ? v : Array.isArray(v) ? v.join(',') : '').split(',').map((x) => x.trim()).filter(Boolean);
  const types = [], features = [], regions = [];
  for (const t of split(query && query.types)) if (FD_CATEGORY_KIND_BY_TYPE[t] && !types.includes(t)) types.push(t);
  for (const f of split(query && query.features)) if (FD_HUB_FEATURE_KEYS.has(f) && !features.includes(f)) features.push(f);
  for (const r of split(query && query.regions)) if (REGION_LABELS[r] && !regions.includes(r)) regions.push(r);
  return { types, features, regions };
}
// Contextual counts: each chip shows how many venues it would contribute
// given the OTHER groups' current selection, so a count can never promise
// results a tap won't deliver. A feature chip ignores only its own group's
// other selections in the same way.
function foodDrinkChipCounts(venues, f, catsById, featsById) {
  const types = {}, features = {}, regions = {};
  for (const v of venues) {
    const cats = catsById.get(v.id) || [], feats = featsById.get(v.id) || [];
    if (foodDrinkFilterMatches([], f.features, f.regions, cats, feats, v.region)) for (const t of cats) types[t] = (types[t] || 0) + 1;
    if (foodDrinkFilterMatches(f.types, f.features, [], cats, feats, v.region)) regions[v.region] = (regions[v.region] || 0) + 1;
    if (foodDrinkFilterMatches(f.types, [], f.regions, cats, feats, v.region)) for (const k of feats) features[k] = (features[k] || 0) + 1;
  }
  return { types, features, regions };
}
// The one-line count, shared verbatim by the server and the client twin.
function foodDrinkSummaryText(shown, total, filtered) {
  const noun = total === 1 ? 'place' : 'places';
  return filtered ? `${shown} of ${total} ${noun}` : `${total} ${noun}`;
}
const FD_HUB_SUMMARY_CLIENT_SRC = `function fdSummaryText(shown, total, filtered){
    var noun = total === 1 ? 'place' : 'places';
    return filtered ? (shown + ' of ' + total + ' ' + noun) : (total + ' ' + noun);
  }`;

// ---------- Open Now on the Food & Drink hub (2026-09-26) ----------
// Per-venue status for /food-drink: venues with stored hours and no advisory get
// hours.js's open/closed status on the Okanagan clock (no provenance requirement,
// as /browse); every other venue gets NO status line at all -- never "Closed",
// and it is never counted as open. The page script recomputes the eligible venues'
// status live in the browser with the same hours.js functions, so the
// render-time status here is the no-script / first-paint value.
const BROWSE_OPEN_NOTE = 'Open Now uses recently verified hours. Hours can change for holidays, seasons or special closures.';
const FD_OPEN_NOTE = 'Open Now is based on each place\u2019s listed hours. Hours can change for holidays, seasons or special closures \u2014 check with the venue before you go.';
// opts.requireVerified (default true) gates on recorded hours verification.
// /food-drink and /browse both pass false: stored hours and the Okanagan clock
// decide, so only a venue with no hours, or with a temporary-closure advisory,
// is left without a status.
function foodDrinkOpenNowInfo(venues, advisoryNotes, now = new Date(), opts = {}) {
  const { requireVerified = true } = opts;
  const byId = new Map();
  const openIds = new Set();
  const provenance = requireVerified ? getHoursProvenanceById(venues.map((v) => v.id)) : new Map();
  const clock = okanaganClock(now);
  // A season note that does not say the venue is closed today ("open until",
  // "reopening") is shown on the card but leaves its Open Now status alone.
  const seasonOk = seasonNonBlockingIds(now);
  for (const v of venues) {
    const hasAdvisory = advisoryNotes.has(v.id) && !seasonOk.has(v.id);
    const e = requireVerified
      ? openNowEligibility(v, provenance.get(v.id), { policy: 'food_drink', now, hasAdvisory })
      : !v.hours ? { eligible: false, reason: 'no_hours' } : hasAdvisory ? { eligible: false, reason: 'advisory' } : { eligible: true, reason: 'ok' };
    if (!e.eligible || !hoursModule) {
      byId.set(v.id, { eligible: false, reason: e.reason, state: null, text: null, hours: null });
      continue;
    }
    // Seasonal hours and special closures ride along (2026-10-18), so the cards' and the map's live status apply them too.
    const raw = hoursWithExtras(v, now);
    const parsed = hoursModule.parseHours(raw);
    const label = hoursModule.hoursStatusLabel(hoursModule.statusAt(parsed, clock), clock);
    byId.set(v.id, { eligible: true, reason: 'ok', state: label.state, text: label.text, hours: JSON.parse(raw) });
    if (label.state === 'open') openIds.add(v.id);
  }
  return { byId, openIds };
}
function foodDrinkOpenNowToggleHtml(on, count) {
  return `<button type="button" class="fd-pop-btn fd-open-toggle" id="fdOpenNow" data-fd-open-now aria-pressed="${on ? 'true' : 'false'}"><span class="fd-pop-icon" aria-hidden="true">🕒</span> Open now<span class="outdoor-activity-count" id="fdOpenNowCount">${count}</span></button>`;
}
// Emitted only by the /food-drink hub, so the destination category pages
// (which share renderFoodDrinkHubStyles) are unchanged.
function renderFoodDrinkOpenNowStyles() {
  return `<style>
  /* The toggle is a filter, not a popover. Pressed, it takes this page's
     selected-chip treatment (navy fill + the teal ring the type chips use)
     so it never reads as an open panel; hover on the pressed state goes
     navy-deep like the selected tags. */
  body.fd-page .fd-open-toggle[aria-pressed="true"] { background: var(--ref-navy, #1B2B3A); color: var(--paper); border-color: var(--ref-navy, #1B2B3A); box-shadow: 0 0 0 2px var(--paper), 0 0 0 4px var(--teal, #2A6B67); }
  body.fd-page .fd-open-toggle[aria-pressed="true"]:hover { background: var(--ref-navy-deep, #101B24); border-color: var(--ref-navy-deep, #101B24); }
  body.fd-page .fd-open-toggle .outdoor-activity-count { margin-left: 0; }
  body.fd-page .fd-open-toggle[aria-pressed="true"] .outdoor-activity-count { opacity: 0.8; }
  body.fd-page .fd-open-note { margin: -2px 0 14px; font-family: 'Nunito', 'Nunito Fallback', sans-serif; font-size: 0.8rem; line-height: 1.45; color: var(--ink-muted, #6B5D54); max-width: 64ch; text-wrap: pretty; }
  /* Open-now footnote (2026-10-14): under the list always; above it only while Open now is on. */
  body.fd-page .fd-controls + .fd-open-note { display: none; }
  body.fd-page .fd-controls:has(.fd-open-toggle[aria-pressed="true"]) + .fd-open-note { display: block; }
  body.fd-page .fd-open-note-end { margin: 6px auto 0; text-align: center; }
  /* Open-now empty state (2026-10-18): the next places to open, under the no-results line. */
  body.fd-page .fd-open-next { margin: 10px 0 0; font-weight: 400; }
  body.fd-page .fd-open-next-title { margin: 0 0 4px; font-weight: 700; }
  body.fd-page .fd-open-next ul { margin: 0; padding-left: 18px; }
  body.fd-page .fd-open-next li { margin: 2px 0; }
  body.fd-page .fd-open-next-when { white-space: nowrap; }
  /* Review pass 5 (2026-10-19): the Show all button, and the Opening next links as 44px tap targets. */
  .fd-open-next .fd-open-next-all { display: inline-flex; align-items: center; min-height: 44px; margin: 0 0 10px; padding: 0 18px; border: 1px solid var(--ref-navy, #1B2B3A); border-radius: 999px; background: var(--paper, #FFFCF6); color: var(--ref-navy, #1B2B3A); font: inherit; font-family: 'Nunito', 'Nunito Fallback', sans-serif; font-weight: 800; font-size: 0.9rem; cursor: pointer; }
  .fd-open-next .fd-open-next-all:hover { background: rgba(27,43,58,0.06); }
  .fd-open-next .fd-open-next-all:focus-visible { outline: 3px solid var(--teal, #2A6B67); outline-offset: 2px; }
  .fd-open-next li a { display: inline-flex; align-items: center; min-height: 44px; }
  /* Card status line: one cluster with the meta line (4px under it), then
     the meta line's own 10px before the description. The .venue-card
     selector outranks the golf theme's ".venue-card p" sizing. Filled dot =
     open, hollow dot = closed, no dot when today's hours are not listed. */
  /* Two-up card rows (2026-10-12): the open-now line has its own row under the meta (see the golf theme's card rows). */
  @supports (grid-template-rows: subgrid) { @media (min-width: 900px) { body.golf-page .card-grid > .venue-card > .fd-open-status { grid-row: 3; } } }
  body.fd-page .venue-card .fd-open-status { display: flex; align-items: center; gap: 7px; margin: -6px 0 10px; font-family: 'Nunito', 'Nunito Fallback', sans-serif; font-size: 0.84rem; font-weight: 700; line-height: 1.3; color: var(--ink); opacity: 1; }
  body.fd-page .venue-card .fd-open-status::before { content: ""; flex: 0 0 auto; width: 8px; height: 8px; border-radius: 999px; background: currentColor; }
  body.fd-page .venue-card .fd-open-status[data-fd-open="open"] { color: var(--teal, #2A6B67); font-weight: 800; }
  body.fd-page .venue-card .fd-open-status[data-fd-open="closed"] { opacity: 0.78; }
  body.fd-page .venue-card .fd-open-status[data-fd-open="closed"]::before { background: transparent; box-shadow: inset 0 0 0 1.5px currentColor; }
  body.fd-page .venue-card .fd-open-status[data-fd-open="unknown"] { opacity: 0.6; }
  body.fd-page .venue-card .fd-open-status[data-fd-open="unknown"]::before { display: none; }
</style>`;
}

function foodDrinkSearchHtml() {
  return `<div class="fd-search">
    <label class="visually-hidden" for="fdSearch">Search food and drink</label>
    <input type="search" id="fdSearch" class="fd-search-input" placeholder="Search by name, place or dish..." autocomplete="off" spellcheck="false">
    <button type="button" class="fd-search-clear" id="fdSearchClear" aria-label="Clear search" hidden>&#215;</button>
  </div>`;
}
// Venue-type chips: "All" plus the five categories. "All" is a reset control
// (data-fd-type-all), not a sixth type -- it is pressed exactly when no type
// is chosen, which is already what "no constraint" means to the predicate.
function foodDrinkTypeChipsHtml(state = {}) {
  const selected = new Set(state.types || []);
  const counts = state.counts && state.counts.types ? state.counts.types : null;
  const all = `<button type="button" class="outdoor-filter-chip fd-type-chip fd-type-all" data-fd-type-all="1" aria-pressed="${selected.size ? 'false' : 'true'}">All</button>`;
  const chips = FD_HUB_TYPES.map((t) => {
    const n = counts ? (counts[t.type] || 0) : null;
    return `<button type="button" class="outdoor-filter-chip fd-type-chip" data-fd-type="${t.type}" aria-pressed="${selected.has(t.type) ? 'true' : 'false'}">${escapeHtml(t.label)}${n === null ? '' : ` <span class="outdoor-activity-count">${n}</span>`}</button>`;
  }).join('');
  return `<div class="fd-type-row" role="group" aria-label="Choose venue types" data-filter="fd-type">${all}${chips}</div>`;
}
// "What are you looking for?" -- the FD_HUB_FEATURES badge columns, as
// toggles inside a popover so the page does not become a wall of controls.
function foodDrinkFeatureChipsHtml(state = {}, onlyKeys = null) {
  const selected = new Set(state.features || []);
  const counts = state.counts && state.counts.features ? state.counts.features : null;
  const chips = FD_HUB_FEATURES.filter((f) => (onlyKeys ? onlyKeys.includes(f.key) : !ACTIVITY_ONLY_BADGES.has(f.key))).map((f) => {
    const n = counts ? (counts[f.key] || 0) : null;
    return `<button type="button" class="outdoor-filter-chip fd-feature-chip" data-fd-feature="${f.key}" aria-pressed="${selected.has(f.key) ? 'true' : 'false'}"><span class="fd-feature-icon" aria-hidden="true">${f.icon}</span> ${escapeHtml(f.label)}${n === null ? '' : ` <span class="outdoor-activity-count">${n}</span>`}</button>`;
  }).join('');
  return `<div class="fd-feature-grid" role="group" aria-label="Choose what you are looking for" data-filter="fd-feature">${chips}</div>`;
}
// The two popovers. Regions reuses renderOutdoorRegionFilterChips() verbatim,
// so the canonical 20-region list and its FOOTER_REGION_GROUPS grouping are
// literally the same code the other directories use -- no second region
// system, and it cannot drift.
function foodDrinkFilterBarHtml(venues, state = {}, scopeFeatures = null) {
  const nF = (state.features || []).length, nR = (state.regions || []).length;
  // A destination category page (scopeFeatures set) offers only "What are you
  // looking for?", with just the features that page's venues actually have --
  // the region is fixed by the URL, so there is no Regions popover.
  if (scopeFeatures) {
    if (!scopeFeatures.length) return '';
    return `<div class="fd-controls">
    <div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="fdFeaturesBtn" aria-expanded="false" aria-controls="fdFeaturesPanel"><span class="fd-pop-icon" aria-hidden="true">✨</span> <span class="fd-pop-long">What are you looking for?</span><span class="fd-pop-short">Filters</span><span class="fd-pop-count" id="fdFeaturesCount"${nF ? '' : ' hidden'}>${nF ? ` · ${escapeHtml(String(nF))}` : ''}</span></button>
      <div class="fd-pop-panel" id="fdFeaturesPanel" hidden>${foodDrinkFeatureChipsHtml(state, scopeFeatures)}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-fd-apply>Show results</button></div>
      </div>
    </div>
  </div>`;
  }
  const pop = (id, label, icon, badge, panel) => `<div class="fd-pop">
      <button type="button" class="fd-pop-btn" id="${id}Btn" aria-expanded="false" aria-controls="${id}Panel"><span class="fd-pop-icon" aria-hidden="true">${icon}</span> ${label}<span class="fd-pop-count" id="${id}Count"${badge ? '' : ' hidden'}>${badge ? ` · ${escapeHtml(String(badge))}` : ''}</span></button>
      <div class="fd-pop-panel" id="${id}Panel" hidden>${panel}
        <div class="fd-pop-actions"><button type="button" class="fd-pop-apply" data-fd-apply>Show results</button></div>
      </div>
    </div>`;
  return `<div class="fd-controls">
    ${pop('fdFeatures', '<span class="fd-pop-long">What are you looking for?</span><span class="fd-pop-short">Filters</span>', '✨', nF || '', foodDrinkFeatureChipsHtml(state))}
    ${pop('fdRegions', 'Regions', '📍', nR || '', renderOutdoorRegionFilterChips(venues, { selectedRegions: state.regions || [], counts: state.counts }))}
  </div>`;
}
// Removable active-filter tags, one row per group, plus Clear all.
function foodDrinkSelectedTagsHtml(state = {}) {
  const tag = (kind, v, label) => `<button type="button" class="outdoor-selected-tag" data-fd-remove-${kind}="${escapeHtml(v)}" aria-label="Remove ${escapeHtml(label)}">${escapeHtml(label)}<span class="outdoor-selected-x" aria-hidden="true">×</span></button>`;
  const row = (label, tags) => (tags.length ? `<div class="outdoor-selected-row"><span class="outdoor-selected-label">${label}</span> ${tags.join(' ')}</div>` : '');
  const t = (state.types || []).map((x) => tag('type', x, FD_HUB_LABEL_BY_TYPE[x] || x));
  const f = (state.features || []).map((x) => tag('feature', x, FD_HUB_LABEL_BY_FEATURE[x] || x));
  const r = (state.regions || []).map((x) => tag('region', x, REGION_LABELS[x] || x));
  const o = state.openNow ? [tag('open', 'now', 'Open now')] : [];
  const any = t.length + f.length + r.length + o.length > 0;
  return `<div class="outdoor-selected" id="fdSelected"${any ? '' : ' hidden'}>${row('Types', t)}${row('Looking for', f)}${row('Regions', r)}${row('Hours', o)}${any ? '<button type="button" class="outdoor-selected-clear" id="fdSelectedClear">Clear all</button>' : ''}</div>`;
}
function foodDrinkResultBarHtml(summary, state, sort = null, sorts = FD_SORTS) {
  // Sort (hub only, 2026-10-14): a native select, so it is a phone's own
  // picker and keyboard-accessible with no extra code.
  const sortHtml = sort ? `
    <label class="fd-sort"><span class="fd-sort-label">Sort</span> <select id="fdSort" class="fd-sort-select">${sorts.map((o) => `<option value="${o.key}"${o.key === sort ? ' selected' : ''}>${escapeHtml(o.label)}</option>`).join('')}</select></label>` : '';
  return `<div class="fd-resultbar">
    <p class="fd-count" id="fdResultsSummary" aria-live="polite">${escapeHtml(summary)}</p>${sortHtml}
  </div>
  ${foodDrinkSelectedTagsHtml(state)}`;
}

