    catsFor: (v) => { const a = tourActivityOf(v); return a ? [a] : []; },
    photoKeyFor: (v) => { const a = tourActivityOf(v); return curatedPhotoKey(v, a ? `tour${a}` : 'tour'); },
    cardNotes: getToursAlsoNotes(),
