    ...liveActivityPagePaths().map((path) => `  <url>\n    <loc>https://okanaganroam.com${path}</loc>\n    <lastmod>${today}</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.7</priority>\n  </url>`),
