    ...listLiveOutdoorActivities().map(
      ({ slug }) =>
        `  <url>\n    <loc>https://okanaganroam.com/outdoors/${slug}</loc>\n    <lastmod>${today}</lastmod>\n    <changefreq>weekly</changefreq>\n    <priority>0.7</priority>\n  </url>`
    ),
