// A guide place by 'region/slug' (live), and its public URL.
// Event refs (2026-10-13) are written 'event:region/slug': a scheduled event
// that hasn't ended yet links to its page; a past, cancelled or missing one
// drops out of the guide on its own, so seasonal guides never point at
// events that are over.
function guideRefVenue(ref) {
  const r = String(ref);
  if (r.startsWith('event:')) {
    const [region, slug] = r.slice(6).split('/');
    const e = REGION_LABELS[region] ? findEventBySlug(region, slug) : null;
    const full = e ? getEventById(e.id) : null;
    if (!full || full.status !== 'scheduled' || isEventExpired(full)) return null;
    return { region, slug, name: full.name, _href: `/${region}/events/${slug}` };
  }
  const [region, slug] = r.split('/');
  return skiGuideVenue(region, slug);
}
const guideVenueHref = (v) => v._href || `/${v.region}/${CATEGORY_SLUGS[v.type]}/${v.slug}`;
// Tip text with {region/slug|Label} links resolved live; everything else escaped.
function guideTipHtml(text) {
  return String(text).split(/(\{(?:page:\/[a-z0-9\/_-]*|(?:event:)?[a-z-]+\/[a-z0-9-]+)\|[^}]+\})/).map((part) => {
    // {page:/path|Label}: a plain internal link (another guide, a list page).
    const pg = part.match(/^\{page:(\/[a-z0-9\/_-]*)\|([^}]+)\}$/);
    if (pg) return `<a href="${escapeHtml(pg[1])}">${escapeHtml(pg[2])}</a>`;
    const m = part.match(/^\{((?:event:)?[a-z-]+\/[a-z0-9-]+)\|([^}]+)\}$/);
    if (!m) return escapeHtml(part);
    const v = guideRefVenue(m[1]);
    return v ? `<a href="${escapeHtml(guideVenueHref(v))}">${escapeHtml(m[2])}</a>` : escapeHtml(m[2]);
  }).join('');
}
function renderWineGuidePage() { return renderEditorialGuidePage(WINE_GUIDE, WINE_GUIDE_PATH); }
// Shared page for the region/slug-based editorial guides (wine, dog-friendly).
function renderEditorialGuidePage(g, path) {
  const banner = g.banner();
  const thin = guideIsThin(g);
  const canonical = `https://okanaganroam.com${path}`;
  const breadcrumb = breadcrumbListSchema([
    { name: 'Home', url: 'https://okanaganroam.com/' },
    { name: g.parent.name, url: `https://okanaganroam.com${g.parent.href}` },
    { name: g.heading, url: canonical },
  ]);
  const article = {
    '@context': 'https://schema.org',
    '@type': 'Article',
    headline: g.heading,
    description: g.description,
    image: `https://okanaganroam.com${banner.src}`,
    mainEntityOfPage: canonical,
    publisher: { '@type': 'Organization', name: 'Okanagan Roam', url: 'https://okanaganroam.com/' },
  };
  const listed = [];
  const itemHtml = (item) => {
    if (item.tip) return `\n          <li><strong>${escapeHtml(item.lead)}</strong> ${guideTipHtml(item.tip)}</li>`;
    const v = guideRefVenue(item.ref);
    if (!v) return '';
    listed.push({ name: item.name || v.name, url: `https://okanaganroam.com${guideVenueHref(v)}` });
    const place = item.where || (item.noPlace || g.noPlace ? '' : REGION_LABELS[v.region] || '');
    return `\n          <li><strong><a href="${escapeHtml(guideVenueHref(v))}">${escapeHtml(item.name || v.name)}</a></strong>${place ? ` (${escapeHtml(place)})` : ''}: ${guideTipHtml(item.text)}</li>`;
  };
  // Only sections (and quick-pick rows) with at least one live place render,
  // and the jump links follow what rendered, so a closed place never leaves
  // an empty heading or a dead jump link.
  const liveSections = new Set();
  const sectionsHtml = g.sections.map((sec) => {
    const items = sec.items.map(itemHtml).join('');
    if (items) liveSections.add(sec.id);
    return items ? `\n      <section class="ski-guide-resort" id="${sec.id}">\n        <h2>${escapeHtml(sec.heading)}</h2>${sec.lead ? `\n        <p>${guideTipHtml(sec.lead)}</p>` : ''}\n        <ul class="ski-guide-list">${items}\n        </ul>\n      </section>` : '';
  }).join('');
  const rowsHtml = g.table.rows.map(([area, refs]) => {
    const links = refs.map((x) => { const [ref, label] = x.split('|'); const v = guideRefVenue(ref); return v ? `<a href="${escapeHtml(guideVenueHref(v))}">${escapeHtml(label)}</a>` : ''; }).filter(Boolean);
    return links.length ? `\n          <tr><th scope="row">${escapeHtml(area)}</th><td>${links.join(', ')}</td></tr>` : '';
  }).join('');
  return `<!DOCTYPE html>
<html lang="en">
<head>
${pageHead(g.title, g.description, canonical, [breadcrumb, article, guideItemListSchema(g.heading, canonical, listed)].filter(Boolean), { golfTheme: true, shareImage: banner.src, noindex: thin })}
${renderAnalyticsHeadHtml('guide')}
${CATEGORY_BANNER_STYLE}
<style>
  body.ski-guide-page .ski-guide { max-width: 760px; margin: 0 auto; padding: 12px 0 48px; }
  body.ski-guide-page .ski-guide-intro p { font-size: 1.05rem; line-height: 1.6; }
  body.ski-guide-page .ski-guide-jump { display: flex; gap: 10px; flex-wrap: wrap; margin: 18px 0 8px; }
  body.ski-guide-page .ski-guide-jump a { background: var(--paper); border-radius: 999px; padding: 8px 16px; font-weight: 700; text-decoration: none; }
  body.ski-guide-page .ski-guide-resort { margin-top: 32px; }
  body.ski-guide-page .ski-guide-list { padding-left: 1.2em; margin: 0; }
  body.ski-guide-page .ski-guide-list li { margin: 0 0 10px; line-height: 1.55; }
  body.ski-guide-page .patio-picks { width: 100%; border-collapse: collapse; margin: 8px 0 18px; }
  body.ski-guide-page .patio-picks th, body.ski-guide-page .patio-picks td { text-align: left; vertical-align: top; padding: 10px 8px; border-bottom: 1px solid rgba(27,43,58,.12); line-height: 1.5; }
  body.ski-guide-page .patio-picks thead th { font-size: .85rem; text-transform: uppercase; letter-spacing: .04em; color: var(--ink-muted, #6B5D54); }
  body.ski-guide-page .patio-picks tbody th { width: 38%; font-weight: 700; }
</style>
</head>
<body class="golf-page ski-guide-page">
  ${renderGolfTripTrayHtml()}
<div id="floatingTooltip"></div>
${renderGolfHeaderHtml()}
  <main class="wrap-wide golf-main" id="main">
  ${breadcrumbNavHtml([
    { name: 'Home', href: '/' },
    { name: g.parent.name, href: g.parent.href },
    { name: g.heading },
  ])}
    <article class="ski-guide">
      ${categoryHeroHtml(`<div class="category-banner"><img src="${banner.src}" alt="${escapeHtml(banner.alt)}" width="1600" height="1067" style="object-position: 50% ${banner.pos}%" fetchpriority="high"></div>`, `<h1>${escapeHtml(g.heading)}</h1>`)}
      ${thin ? `<p class="guide-thin-note"><strong>This guide is between seasons.</strong> Most of what it covered has finished for now. See our <a href="/guides">current guides</a>.</p>\n      ` : ''}<div class="ski-guide-intro">${g.intro.map((p) => `\n        <p>${guideTipHtml(p)}</p>`).join('')}
      </div>
      <nav class="ski-guide-jump" aria-label="Jump to a section">${g.sections.filter((sec) => liveSections.has(sec.id)).map((sec) => `<a href="#${sec.id}">${escapeHtml(sec.jump)}</a>`).join('')}${rowsHtml ? `<a href="#${g.table.id}">${escapeHtml(g.table.jump)}</a>` : ''}</nav>${sectionsHtml}
      <section class="ski-guide-resort" id="${g.table.id}">${rowsHtml ? `
        <h2>${escapeHtml(g.table.heading)}</h2>
        <table class="patio-picks">
          ${g.table.head ? `<thead><tr><th scope="col">${escapeHtml(g.table.head[0])}</th><th scope="col">${escapeHtml(g.table.head[1])}</th></tr></thead>` : ''}
          <tbody>${rowsHtml}
          </tbody>
        </table>` : ''}
        <p>${g.footerHtml}</p>
        <p><a href="/guides">More Okanagan guides &rarr;</a></p>
      </section>
    </article>
  </main>
  ${renderHomeFooterHTML(true)}
  ${GOLF_APP_SCRIPT_TAG}
</body>
</html>`;
}

