  h = h.split('\n').map((l) => {
    const b = /^\s*<(strong|b)\b[^>]*>([\s\S]*)<\/\1>\s*$/i.exec(l);
    return b && !new RegExp('</' + b[1] + '>', 'i').test(b[2]) && b[2].replace(/<[^>]+>/g, '').trim() ? '\u00017\u0002' + b[2] : l;
  }).join('\n').replace(/<[^>]+>/g, '');
