// Applies an approved request. `fields` (optional) approves only some of the
// changed fields. Each field goes through its guarded writer; any failure
// rolls the whole approval back and leaves the request pending.
function approveOwnerChange(id, reviewer, fields, now = new Date()) {
  const req = getOwnerChange(id);
  if (!req) return { ok: false, reason: 'not_found' };
  if (req.status !== 'pending') return { ok: false, reason: 'not_pending', status: req.status };
  const venue = db.prepare('SELECT * FROM venues WHERE id = ?').get(req.venue_id);
  if (!venue || venue.redirect_to) return { ok: false, reason: 'venue_unavailable' };
  const chosen = Array.isArray(fields) && fields.length ? fields.filter((f) => f in req.changes) : Object.keys(req.changes);
  if (!chosen.length) return { ok: false, reason: 'no_fields' };
  const meta = { reason: `owner request #${id}`, batch_id: `owner-${todayLocal(now)}`, reviewed_by: reviewer };
  const r = applyOwnerFields(venue, req.changes, chosen, meta, reviewer, now);
  if (!r.ok) return r;
  db.prepare("UPDATE owner_change_requests SET status = 'approved', reviewed_at = CURRENT_TIMESTAMP, reviewed_by = ? WHERE id = ?").run(reviewer, id);
  return { ok: true, applied: r.applied, listing: r.listing };
}

// Writes owner fields onto a venue (`venue` is its raw row) through each field's guarded writer, logging every one
// to venue_enrichment_log as 'venue_owner'. Used by approval, by a signed-in owner's instant save (2026-10-18), and
// by Undo (opts.undo: `values` are the old values; hours get their old provenance back from opts.undoMeta).
function applyOwnerFields(venue, values, chosen, meta, reviewer, now = new Date(), opts = {}) {
  const listing = venueListingUrl(venue);
  const applied = [];
  const log = db.prepare(`INSERT INTO venue_enrichment_log
    (venue_id, field_name, old_value, new_value, source, source_ref, confidence, batch_id, auto_accepted, reviewed_by)
    VALUES (?, ?, ?, ?, 'venue_owner', ?, 'high', ?, 0, ?)`);
  db.exec('SAVEPOINT owner_approve');
  try {
    for (const field of chosen) {
      const value = values[field];
      if (field === 'hours') {
        // guardedHoursVerifyUpdate runs its own BEGIN/COMMIT, which SQLite
        // does not allow inside a savepoint -- so hours are written last,
        // outside it (below).
        continue;
      }
      if (field === 'happy_hour') continue; // same reason; written below
      if (OWNER_LINK_FIELDS.includes(field) || field === 'open_months') {
        const before = venueLinks(venue.id)[field];
        const next = value === '' ? null : value;
        db.prepare(`INSERT INTO venue_links (venue_id, ${field}) VALUES (?, ?) ON CONFLICT(venue_id) DO UPDATE SET ${field} = excluded.${field}, updated_at = CURRENT_TIMESTAMP`).run(venue.id, next);
        clearVenueSocialCache();
        log.run(venue.id, field, before == null ? null : String(before), next == null ? null : String(next), meta.reason, meta.batch_id, reviewer);
        applied.push(field);
        continue;
      }
      // Price range (2026-10-18): venues.price, 1-4 ($ to $$$$).
      if (field === 'price_range') {
        const next = value === '' || value == null ? null : Number(value);
        updateVenue(venue.id, { price: next });
        log.run(venue.id, 'price', venue.price == null ? null : String(venue.price), next == null ? null : String(next), meta.reason, meta.batch_id, reviewer);
        applied.push(field);
        continue;
      }
      // Seasonal hours and special closures (2026-10-18): venue_hours_extra.
      if (field === 'hours_seasons' || field === 'closures') {
        const col = field === 'hours_seasons' ? 'seasons' : 'closures';
        const beforeRow = db.prepare(`SELECT ${col} AS v FROM venue_hours_extra WHERE venue_id = ?`).get(venue.id);
        const json = Array.isArray(value) && value.length ? JSON.stringify(value) : null;
        db.prepare(`INSERT INTO venue_hours_extra (venue_id, ${col}) VALUES (?, ?) ON CONFLICT(venue_id) DO UPDATE SET ${col} = excluded.${col}, updated_at = CURRENT_TIMESTAMP`).run(venue.id, json);
        clearHoursExtraCache();
        log.run(venue.id, field === 'hours_seasons' ? 'hours_seasons' : 'hours_closures', beforeRow ? beforeRow.v : null, json, meta.reason, meta.batch_id, reviewer);
        applied.push(field);
        continue;
      }
      if (field === 'badges') {
        const update = {};
        for (const [k, on] of Object.entries(value)) {
          update[k] = on;
          log.run(venue.id, k, String(venue[k] ? 1 : 0), on ? '1' : '0', meta.reason, meta.batch_id, reviewer);
        }
        updateVenue(venue.id, update);
      } else {
        const next = value === '' ? null : value;
        updateVenue(venue.id, { [field]: next });
        log.run(venue.id, field, venue[field] == null ? null : String(venue[field]), next == null ? null : String(next), meta.reason, meta.batch_id, reviewer);
      }
      applied.push(field);
    }
    // New seasonal hours or closures from the owner also count as the owner checking the hours (2026-10-18): the
    // venue page then says "Hours checked" with today's date. Undo puts the old provenance back instead.
    const extrasTouched = chosen.includes('hours_seasons') || chosen.includes('closures');
    if (extrasTouched && !chosen.includes('hours') && venue.hours) {
      const u = opts.undo ? (opts.undoMeta || {}) : { hours_source: 'venue_owner', hours_checked_at: todayLocal(now) };
      const next = { hours_source: u.hours_source || null, hours_checked_at: u.hours_checked_at || null };
      db.prepare('UPDATE venues SET hours_source = ?, hours_checked_at = ? WHERE id = ?').run(next.hours_source, next.hours_checked_at, venue.id);
      for (const f of ['hours_source', 'hours_checked_at']) {
        if ((venue[f] || null) !== next[f]) log.run(venue.id, f, venue[f] == null ? null : String(venue[f]), next[f], meta.reason, meta.batch_id, reviewer);
      }
    }
    db.exec('RELEASE owner_approve');
  } catch (err) {
    try { db.exec('ROLLBACK TO owner_approve'); db.exec('RELEASE owner_approve'); } catch (_) { /* already gone */ }
    return { ok: false, reason: 'write_failed', detail: String(err.message || err) };
  }
  if (chosen.includes('hours')) {
    if (opts.undo) {
      // Back to exactly what was there, which may be no hours at all (the guarded writer only takes valid hours).
      const u = opts.undoMeta || {};
      const next = values.hours || null;
      const info = db.prepare('UPDATE venues SET hours = ?, hours_source = ?, hours_checked_at = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ? AND hours IS ?')
        .run(next, next ? (u.hours_source || null) : null, next ? (u.hours_checked_at || null) : null, venue.id, venue.hours);
      if (info.changes !== 1) return { ok: false, reason: 'hours_failed', detail: 'mismatch', applied };
      syncDerivedHoursBadges(venue.id);
      log.run(venue.id, 'hours', venue.hours == null ? null : String(venue.hours), next, meta.reason, meta.batch_id, reviewer);
    } else {
      const r = guardedHoursVerifyUpdate(venue.id, venue.hours, { hours: values.hours, hours_source: 'venue_owner', hours_checked_at: todayLocal(now) }, meta, now);
      if (!r.ok) return { ok: false, reason: 'hours_failed', detail: r.reason, applied };
    }
    applied.push('hours');
  }
  if (chosen.includes('happy_hour')) {
    const value = values.happy_hour;
    let times = null;
    if (value) {
      const o = JSON.parse(value);
      times = {};
      for (const d of OWNER_DAYS) if (o[d] && o[d].length) times[d] = o[d];
      if (!Object.keys(times).length) times = null;
    }
    const r = guardedHappyHourUpdate(venue.id, venue.happy_hour_times, { times, source_url: listing, checked_at: todayLocal(now) }, { reason: meta.reason, batch_id: meta.batch_id, reviewed_by: reviewer }, now);
    if (!r.ok) return { ok: false, reason: 'happy_hour_failed', detail: r.reason, applied };
    applied.push('happy_hour');
  }
  return { ok: true, applied, listing };
}

// ---------- Instant owner edits and Undo (2026-10-18) ----------
// A signed-in owner's own facts go live at once; a new name, address, website or link still waits for review (they
// change what the listing IS, and are the fields a wrong person would most want to change). An edit link alone stays
// fully reviewed: a link can be forwarded or found in an old email, while a login is one person with a password.
const OWNER_INSTANT_FIELDS = new Set(['hours', 'open_months', 'phone', 'description', 'badges', 'happy_hour', 'price_range', 'hours_seasons', 'closures']);
// More instant saves than this for one listing in a day, and the rest wait for review (a stolen login can't churn it).
const OWNER_INSTANT_DAILY_LIMIT = 30;
function ownerInstantCountToday(venueId) {
  return db.prepare("SELECT COUNT(*) AS n FROM owner_change_requests WHERE venue_id = ? AND instant = 1 AND submitted_at > datetime('now', '-1 day')").get(venueId).n;
}
// Does a live value still match what an instant change set? (Undo only touches fields nobody changed since.)
function ownerFieldEquals(field, a, b) {
  if (field === 'hours' || field === 'happy_hour') return sameJsonWeek(a || null, b || null);
  if (field === 'hours_seasons' || field === 'closures') return JSON.stringify(a || []) === JSON.stringify(b || []);
  return String(a == null ? '' : a) === String(b == null ? '' : b);
}
// Undo one instant change from /admin/review: puts back the old value of every field that still shows what the
// owner set. -> { ok, restored, skipped } or { ok: false, reason }. `reason` (2026-10-18) is kept for the owner's
// "Your updates" ("Changed back by us: ...") and their email.
function undoOwnerInstantChange(id, reviewer, now = new Date(), reason = '') {
  const req = getOwnerChange(id);
  if (!req) return { ok: false, reason: 'not_found' };
  if (!req.instant || req.status !== 'approved') return { ok: false, reason: 'not_instant' };
  if (req.undone_at) return { ok: false, reason: 'already_undone' };
  const row = db.prepare('SELECT * FROM venues WHERE id = ?').get(req.venue_id);
  if (!row || row.redirect_to) return { ok: false, reason: 'venue_unavailable' };
  const current = ownerVenueSnapshot(rowToVenue(row), row.happy_hour_times || null);
  const restore = {};
  const skipped = [];
  for (const [f, val] of Object.entries(req.changes)) {
    if (f === 'badges') {
      const b = {};
      for (const [k, on] of Object.entries(val)) {
        if (current.badges[k] === on) b[k] = !!(req.previous.badges || {})[k]; else skipped.push(k);
      }
      if (Object.keys(b).length) restore.badges = b;
      continue;
    }
    if (ownerFieldEquals(f, current[f], val)) restore[f] = req.previous[f]; else skipped.push(f);
  }
  if (!Object.keys(restore).length) return { ok: false, reason: 'changed_since' };
  let undoMeta = null;
  try { undoMeta = req.undo_meta ? JSON.parse(req.undo_meta) : null; } catch (e) { undoMeta = null; }
  const meta = { reason: `undo owner change #${id}`, batch_id: `owner-undo-${todayLocal(now)}`, reviewed_by: reviewer };
  const r = applyOwnerFields(row, restore, Object.keys(restore), meta, reviewer, now, { undo: true, undoMeta });
  if (!r.ok) return r;
  db.prepare('UPDATE owner_change_requests SET undone_at = CURRENT_TIMESTAMP, undone_by = ? WHERE id = ?').run(reviewer, id);
  const why = String(reason || '').trim().slice(0, 300);
  if (why) { try { db.prepare('UPDATE owner_change_requests SET undo_reason = ? WHERE id = ?').run(why, id); } catch (e) { /* an old copy without the column */ } }
  return { ok: true, restored: r.applied, skipped };
}
// The waiting fields that would go live now for a signed-in owner (2026-10-18): the instant-eligible ones from the
// edit-link request still waiting for review, minus any that already match the listing. -> { live, livePrev, rest,
// restPrev } or null. `current` is ownerVenueSnapshot(); closures already over are dropped.
function ownerPendingInstantSplit(waiting, current) {
  if (!waiting) return null;
  const changes = typeof waiting.changes === 'string' ? JSON.parse(waiting.changes) : waiting.changes;
  const previous = typeof waiting.previous === 'string' ? JSON.parse(waiting.previous) : waiting.previous;
  const live = {}, livePrev = {}, rest = {}, restPrev = {};
  for (const [k, val] of Object.entries(changes)) {
    if (!OWNER_INSTANT_FIELDS.has(k)) { rest[k] = val; if (k in previous) restPrev[k] = previous[k]; continue; }
    if (k === 'badges') {
      const b = {};
      for (const [bk, on] of Object.entries(val || {})) if (!!current.badges[bk] !== !!on) b[bk] = !!on;
      if (Object.keys(b).length) { live.badges = b; livePrev.badges = Object.fromEntries(Object.keys(b).map((f) => [f, !!current.badges[f]])); }
      continue;
    }
    const v = k === 'closures' && Array.isArray(val) ? val.filter((c) => (c.to || c.from) >= todayLocal()) : val;
    if (ownerFieldEquals(k, current[k], v)) continue;
    live[k] = v;
    livePrev[k] = current[k];
  }
  return { live, livePrev, rest, restPrev };
}
// Pending link changes go live (2026-10-18): an owner who sent hours or a phone number from the edit link and then
// creates a login (or adds the listing to one) used to see them stuck on "Waiting for review" under a header saying
// they go live straight away, because Save only sends the fields changed on the page. Now the instant-eligible ones
// are published through the same path as an instant save: an instant=1 audit row with Undo, attributed to the
// login: the person creating it holds the edit link right now, so they could have saved those fields anyway. A new
// name, address, website or link stays waiting.
// Not done when a signed-in owner just opens a listing: the waiting request may merge several people's link sends
// (and their emails), so it can't be pinned on this login. Instead the next signed-in Save carries them (see
// handleOwnerChangeSubmission) and the banner above the form says so.
// -> { id, fields } or null when nothing went live.
function publishPendingOwnerInstant(venueId, account) {
  if (!account || !account.email) return null;
  const waiting = db.prepare("SELECT * FROM owner_change_requests WHERE venue_id = ? AND status = 'pending' AND instant = 0 ORDER BY id DESC LIMIT 1").get(venueId);
  if (!waiting) return null;
  if (ownerInstantCountToday(venueId) >= OWNER_INSTANT_DAILY_LIMIT) return null;
  const row = db.prepare('SELECT * FROM venues WHERE id = ?').get(venueId);
  if (!row || row.redirect_to) return null;
  const split = ownerPendingInstantSplit(waiting, ownerVenueSnapshot(rowToVenue(row), row.happy_hour_times || null));
  if (!split || !Object.keys(split.live).length) return null;
  const { live, livePrev, rest, restPrev } = split;
  const restLeft = Object.keys(rest).length > 0;
  const reviewer = `owner:${account.email}`;
  let liveId;
  db.exec('BEGIN');
  try {
    if (restLeft) db.prepare('UPDATE owner_change_requests SET changes = ?, previous = ? WHERE id = ?').run(JSON.stringify(rest), JSON.stringify(restPrev), waiting.id);
    else db.prepare("UPDATE owner_change_requests SET status = 'superseded', reviewed_at = CURRENT_TIMESTAMP, reviewed_by = ? WHERE id = ?").run(reviewer, waiting.id);
    liveId = Number(db.prepare('INSERT INTO owner_change_requests (venue_id, changes, previous, note, contact_name, contact_email, ip_hash, instant, undo_meta) VALUES (?, ?, ?, ?, ?, ?, ?, 1, ?)')
      .run(venueId, JSON.stringify(live), JSON.stringify(livePrev), restLeft ? null : waiting.note, waiting.contact_name, account.email, waiting.ip_hash,
        JSON.stringify({ hours_source: row.hours_source || null, hours_checked_at: row.hours_checked_at || null, from_request: waiting.id })).lastInsertRowid);
    try { if (waiting.lang) db.prepare('UPDATE owner_change_requests SET lang = ? WHERE id = ?').run(waiting.lang, liveId); } catch (e) { /* an old copy without the column */ }
    db.exec('COMMIT');
  } catch (err) {
    try { db.exec('ROLLBACK'); } catch (_) { /* nothing to roll back */ }
    console.error(`[owner-portal] publishing waiting changes for venue #${venueId} failed: ${err.message}`);
    return null;
  }
  const r = approveOwnerChange(liveId, reviewer);
  if (!r.ok) {
    // Put the waiting request back as it was, so nothing is lost.
    db.prepare("UPDATE owner_change_requests SET status = 'rejected', reviewed_at = CURRENT_TIMESTAMP, reviewed_by = 'system', rejection_reason = ? WHERE id = ?")
      .run(`publishing waiting changes failed: ${r.reason}${r.detail ? ` (${String(r.detail).slice(0, 120)})` : ''}`, liveId);
    db.prepare("UPDATE owner_change_requests SET status = 'pending', reviewed_at = NULL, reviewed_by = NULL, changes = ?, previous = ? WHERE id = ?").run(waiting.changes, waiting.previous, waiting.id);
    console.error(`[owner-portal] publishing waiting changes #${waiting.id} for venue #${venueId} failed: ${r.reason} ${r.detail || ''}`);
    return null;
  }
  return { id: liveId, fields: Object.keys(live) };
}
// Instant changes from the last 14 days, newest first, for /admin/review.
function recentInstantOwnerChanges() {
  return db.prepare("SELECT * FROM owner_change_requests WHERE instant = 1 AND status = 'approved' AND submitted_at > datetime('now', '-14 days') ORDER BY id DESC LIMIT 100").all().map((r) => {
    const v = db.prepare('SELECT id, name, region, type, slug FROM venues WHERE id = ?').get(r.venue_id) || {};
    return { ...r, changes: JSON.parse(r.changes), previous: JSON.parse(r.previous), venue_name: v.name, listing_url: venueListingUrl(v) };
  });
}

function rejectOwnerChange(id, reviewer, reason) {
  const req = getOwnerChange(id);
  if (!req) return { ok: false, reason: 'not_found' };
  if (req.status !== 'pending') return { ok: false, reason: 'not_pending', status: req.status };
  db.prepare("UPDATE owner_change_requests SET status = 'rejected', reviewed_at = CURRENT_TIMESTAMP, reviewed_by = ?, rejection_reason = ? WHERE id = ?")
    .run(reviewer, String(reason || '').slice(0, 300) || null, id);
  return { ok: true };
}

// ---------- Admin review page + owner decision emails (2026-10-15) ----------
//
// /admin/review lists everything waiting for Dayton (owner updates, owner
// photos, events, new venues) with Approve / Reject buttons, plus owner photos
// that went live by themselves in the last 14 days (with Remove). It signs in
// once with ENRICHMENT_ADMIN_TOKEN and keeps a 30-day cookie (okr_admin, Path
// /admin, SameSite=Strict) that is an HMAC of its expiry keyed by the token,
// so changing the token signs every browser out. Each decision emails the
// owner (or the person who sent the event / venue) when BREVO_API_KEY is set;
// without it nothing is emailed and owners still see the result in their portal.
const ADMIN_REVIEW_URL = 'https://okanaganroam.com/admin/review';
const ADMIN_SESSION_COOKIE = 'okr_admin';
const ADMIN_SESSION_DAYS = 30;
const ADMIN_LOGIN_RATE_LIMIT = 10;
const ADMIN_REVIEWER = 'dayton';
const OWNER_LOGIN_URL = 'https://okanaganroam.com/owner/login';
const adminLoginAttempts = new Map();

function adminSessionSig(expires) {
  return crypto.createHmac('sha256', ENRICHMENT_ADMIN_TOKEN).update(`okanagan-roam-admin-session:${expires}`).digest('base64url');
}

function makeAdminSession(now = Date.now()) {
  const expires = now + ADMIN_SESSION_DAYS * 86400000;
  return `${expires}.${adminSessionSig(expires)}`;
}

function adminSessionValid(req, now = Date.now()) {
  if (!ENRICHMENT_ADMIN_TOKEN) return false;
  const m = /^(\d{13})\.([A-Za-z0-9_-]{43})$/.exec(readCookie(req, ADMIN_SESSION_COOKIE) || '');
  if (!m || Number(m[1]) < now) return false;
  return safeTokenEquals(m[2], adminSessionSig(m[1]));
}

function adminCookieHeader(req, value, maxAgeSeconds) {
  const secure = String(req.headers['x-forwarded-proto'] || '').split(',')[0].trim() === 'https' || /okanaganroam\.com$/.test(String(req.headers.host || ''));
  return `${ADMIN_SESSION_COOKIE}=${encodeURIComponent(value)}; Path=/admin; HttpOnly; SameSite=Strict; Max-Age=${maxAgeSeconds}${secure ? '; Secure' : ''}`;
}

function adminLoginRateLimited(ip, now = Date.now()) {
  const recent = (adminLoginAttempts.get(ip) || []).filter((t) => now - t < 15 * 60000);
  recent.push(now);
  adminLoginAttempts.set(ip, recent);
  return recent.length > ADMIN_LOGIN_RATE_LIMIT;
}

async function handleAdminReviewLogin(req, res) {
  if (!ENRICHMENT_ADMIN_TOKEN) return sendJSON(res, 503, { ok: false, error: 'Admin review is not configured.' });
  if (!isSameOriginSubmission(req)) return sendJSON(res, 403, { ok: false, error: 'Please sign in from the review page.' });
  if (adminLoginRateLimited(requestClientIp(req))) return sendJSON(res, 429, { ok: false, error: 'Too many attempts. Please wait 15 minutes.' });
  let body;
  try { body = await readBody(req); } catch (err) { return sendJSON(res, 400, { ok: false, error: 'Please try again.' }); }
  const token = body && typeof body.token === 'string' ? body.token.trim() : '';
  if (!token || !safeTokenEquals(token, ENRICHMENT_ADMIN_TOKEN)) return sendJSON(res, 401, { ok: false, error: 'That key is not right.' });
  res.setHeader('Set-Cookie', adminCookieHeader(req, makeAdminSession(), ADMIN_SESSION_DAYS * 86400));
  return sendJSON(res, 200, { ok: true });
}

// --- emails to owners -------------------------------------------------------

// Login emails for the venue, or the contact email on its edit link when no
// one has made a login yet.
function ownerEmailsForVenue(venueId) {
  const emails = db.prepare('SELECT a.email FROM owner_account_venues av JOIN owner_accounts a ON a.id = av.account_id WHERE av.venue_id = ?').all(venueId).map((r) => r.email);
  if (!emails.length) {
    const link = db.prepare('SELECT contact_email FROM venue_owner_links WHERE venue_id = ?').get(venueId);
    if (link && link.contact_email) emails.push(link.contact_email);
  }
  return [...new Set(emails.map((e) => String(e).trim().toLowerCase()).filter((e) => /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(e)))];
}

// Whoever sent it (when they left an email) plus the venue's logins.
function ownerDecisionRecipients(venueId, senderEmail) {
  const sender = senderEmail ? String(senderEmail).trim().toLowerCase() : '';
  return [...new Set([sender, ...ownerEmailsForVenue(venueId)].filter(Boolean))];
}

// What else a business can add from its owner page, in its own words.
function ownerExtrasFor(venue, lang = 'en') {
  const kind = menuKind(venue);
  if (lang === 'fr') {
    if (!MENU_VENUE_TYPES.has(venue.type)) return 'vos liens de réservation et de réseaux sociaux';
    return kind === 'menu' ? 'votre menu' : frDecode(PRICE_LIST_WORDS[kind].fr.listHtml);
  }
  if (!MENU_VENUE_TYPES.has(venue.type)) return 'booking and social links';
  return kind === 'menu' ? 'your menu' : PRICE_LIST_WORDS[kind].en.list;
}

function ownerDecisionEmail({ venueName, what, outcome, reason, link, owner, edited, lang }) {
  if (lang === 'fr') return ownerDecisionEmailFr({ venueName, what, outcome, reason, link, owner, edited });
  const sign = '\n\nThanks,\nOkanagan Roam\ninfo@okanaganroam.com';
  const manage = owner ? `\n\nYou can update your listing, add events or send photos any time: ${OWNER_LOGIN_URL} (no login yet? Get your private edit link at https://okanaganroam.com${OWNER_NEW_LINK_PATH}).` : '';
  if (outcome === 'approved') {
    return {
      subject: `Approved: ${what} for ${venueName}`,
      text: `Hi,\n\nGood news: we approved ${what} for ${venueName}, and it's now live on Okanagan Roam.${edited ? ' We made a small edit before publishing it, so please have a look.' : ''}${link ? `\n\nSee it here: ${link}` : ''}${manage}${sign}`,
    };
  }
  const why = reason ? `\n\nReason: ${reason}` : '';
  if (outcome === 'removed') {
    return {
      subject: `A photo was taken down from ${venueName}`,
      text: `Hi,\n\nWe took ${what} down from the ${venueName} listing on Okanagan Roam.${why}${manage}\n\nQuestions? Email us at info@okanaganroam.com.${sign}`,
    };
  }
  return {
    subject: `Not published: ${what} for ${venueName}`,
    text: `Hi,\n\nThanks for sending ${what} for ${venueName}. We weren't able to publish it this time.${why}${owner ? `\n\nYou can send a corrected version from your business login: ${OWNER_LOGIN_URL}. No login yet? Get your private edit link here: https://okanaganroam.com${OWNER_NEW_LINK_PATH}` : ''}\n\nQuestions? Email us at info@okanaganroam.com.${sign}`,
  };
}

// The same in French (2026-10-18), for something sent from a French portal page. `what` is French already.
function ownerDecisionEmailFr({ venueName, what, outcome, reason, link, owner, edited }) {
  const sign = '\n\nMerci,\nOkanagan Roam\ninfo@okanaganroam.com';
  const manage = owner ? `\n\nVous pouvez mettre à jour votre fiche, ajouter des événements ou envoyer des photos en tout temps : https://okanaganroam.com/fr/owner/login (pas encore de compte? Recevez votre lien de modification privé à https://okanaganroam.com/fr${OWNER_NEW_LINK_PATH}).` : '';
  const why = reason ? `\n\nRaison : ${reason}` : '';
  if (outcome === 'approved') {
    return {
      subject: `Approuvé : ${what} pour ${venueName}`,
      text: `Bonjour,\n\nBonne nouvelle : nous avons approuvé ${what} pour ${venueName}, et c’est maintenant en ligne sur Okanagan Roam.${edited ? ' Nous avons fait une petite retouche avant la publication; jetez-y un coup d’œil.' : ''}${link ? `\n\nVoyez le résultat ici : ${link}` : ''}${manage}${sign}`,
    };
  }
  if (outcome === 'removed') {
    return {
      subject: `Une photo a été retirée de ${venueName}`,
      text: `Bonjour,\n\nNous avons retiré ${what} de la fiche ${venueName} sur Okanagan Roam.${why}${manage}\n\nDes questions? Écrivez-nous à info@okanaganroam.com.${sign}`,
    };
  }
  return {
    subject: `Non publié : ${what} pour ${venueName}`,
    text: `Bonjour,\n\nMerci d’avoir envoyé ${what} pour ${venueName}. Nous n’avons pas pu publier cet envoi cette fois-ci.${why}${owner ? `\n\nVous pouvez envoyer une version corrigée à partir de votre compte entreprise : https://okanaganroam.com/fr/owner/login. Pas encore de compte? Recevez votre lien de modification privé ici : https://okanaganroam.com/fr${OWNER_NEW_LINK_PATH}` : ''}\n\nDes questions? Écrivez-nous à info@okanaganroam.com.${sign}`,
  };
}
// "We changed something back" (2026-10-18): the email after an Undo from /admin/review that came with a reason, in the
// language the change was saved in, to whoever saved it and the listing's logins.
function ownerUndoEmail({ venueName, fields, reason, link, lang }) {
  if (lang === 'fr') {
    return { subject: `Nous avons rétabli une modification de ${venueName}`,
      text: `Bonjour,\n\nNous avons remis l’ancienne version de ${ownerFieldList(fields, 'fr')} sur la fiche ${venueName} d’Okanagan Roam.\n\nRaison : ${reason}${link ? `\n\nVotre fiche : ${link}` : ''}\n\nVous pouvez la mettre à jour de nouveau en tout temps : https://okanaganroam.com/fr/owner/login. Des questions? Répondez à ce courriel ou écrivez à info@okanaganroam.com.\n\nMerci,\nOkanagan Roam` };
  }
  return { subject: `We changed back an update to ${venueName}`,
    text: `Hi,\n\nWe put back the earlier ${ownerFieldList(fields)} on the ${venueName} listing on Okanagan Roam.\n\nReason: ${reason}${link ? `\n\nYour listing: ${link}` : ''}\n\nYou can update it again any time: ${OWNER_LOGIN_URL}. Questions? Reply to this email or write to info@okanaganroam.com.\n\nThanks,\nOkanagan Roam` };
}
// -> 'sent' | 'failed' | 'no_address' | 'email_off'
async function notifyOwnerUndo(id, restored, reason) {
  const r = getOwnerChange(id);
  const v = r && db.prepare('SELECT id, name, region, type, slug FROM venues WHERE id = ?').get(r.venue_id);
  if (!v) return 'no_address';
  const fr = r.lang === 'fr';
  const fields = Array.isArray(restored) && restored.length ? restored : Object.keys(r.changes);
  const email = String(r.reviewed_by || '').startsWith('owner:') ? String(r.reviewed_by).slice(6) : r.contact_email;
  return sendOwnerDecision(ownerDecisionRecipients(v.id, email), ownerUndoEmail({ venueName: v.name, fields, reason: String(reason).trim().slice(0, 300),
    link: fr ? ownerListingUrlFr(v) : venueListingUrl(v), lang: fr ? 'fr' : 'en' }));
}
// An event page in French when it has a French twin (its description is translated), else the English page (2026-10-18).
function ownerEventUrlFr(ev) {
  const p = `/${ev.region}/events/${ev.slug}`;
  return `https://okanaganroam.com${hasFrenchTwin(p) ? `/fr${p}` : p}`;
}
// The venue page in French when it has one.
function ownerListingUrlFr(v) {
  const row = v ? db.prepare('SELECT * FROM venues WHERE id = ?').get(v.id) : null;
  return row && venueHasFrench(row) ? `https://okanaganroam.com${venuePagePath(row, 'fr')}` : venueListingUrl(v);
}

// -> 'sent' | 'failed' | 'no_address' | 'email_off'
async function sendOwnerDecision(to, message) {
  if (!to.length) return 'no_address';
  const send = ownerDirectEmail();
  if (!send) return 'email_off';
  try {
    for (const addr of to) await send({ to: addr, subject: message.subject, text: message.text });
    return 'sent';
  } catch (err) {
    console.error(`[admin-review] decision email failed: ${String((err && err.message) || err).slice(0, 300)}`);
    return 'failed';
  }
}

function ownerFieldList(fields, lang = 'en') {
  const fr = lang === 'fr';
  const names = fields.map((f) => ((fr ? OWNER_FIELD_LABELS_FR : OWNER_FIELD_LABELS)[f] || f).toLowerCase());
  return names.length > 1 ? `${names.slice(0, -1).join(', ')}${fr ? ' et ' : ' and '}${names[names.length - 1]}` : names[0] || (fr ? 'fiche' : 'listing');
}

// Emails whoever sent item `id` after a successful decision. `extra` carries
// what only the caller knows (the fields approved, the reason given).
async function notifyReviewDecision(kind, id, action, extra = {}) {
  const outcome = action === 'approve' ? 'approved' : action === 'remove' ? 'removed' : 'rejected';
  const reason = typeof extra.reason === 'string' ? extra.reason.trim().slice(0, 300) : '';
  if (kind === 'change') {
    const r = getOwnerChange(id);
    const v = r && db.prepare('SELECT id, name, region, type, slug FROM venues WHERE id = ?').get(r.venue_id);
    if (!v) return 'no_address';
    const fields = outcome === 'approved' && Array.isArray(extra.applied) ? extra.applied : Object.keys(r.changes);
    if (r.lang === 'fr') return sendOwnerDecision(ownerDecisionRecipients(v.id, r.contact_email), ownerDecisionEmail({ venueName: v.name, what: `votre mise à jour (${ownerFieldList(fields, 'fr')})`, outcome, reason, edited: !!extra.edited, link: ownerListingUrlFr(v), owner: true, lang: 'fr' }));
    return sendOwnerDecision(ownerDecisionRecipients(v.id, r.contact_email), ownerDecisionEmail({ venueName: v.name, what: `your ${ownerFieldList(fields)} update`, outcome, reason, edited: !!extra.edited, link: venueListingUrl(v), owner: true }));
  }
  if (kind === 'photo') {
    const p = db.prepare('SELECT * FROM owner_photos WHERE id = ?').get(id);
    const v = p && db.prepare('SELECT id, name, region, type, slug FROM venues WHERE id = ?').get(p.venue_id);
    if (!v) return 'no_address';
    if (p.lang === 'fr') return sendOwnerDecision(ownerDecisionRecipients(v.id, p.contact_email), ownerDecisionEmail({ venueName: v.name, what: 'votre photo', outcome, reason, edited: !!extra.edited, link: ownerListingUrlFr(v), owner: true, lang: 'fr' }));
    return sendOwnerDecision(ownerDecisionRecipients(v.id, p.contact_email), ownerDecisionEmail({ venueName: v.name, what: 'your photo', outcome, reason, edited: !!extra.edited, link: venueListingUrl(v), owner: true }));
  }
  if (kind === 'event') {
    const s = getEventSubmission(id);
    if (!s) return 'no_address';
    const venue = s.owner_venue_id ? db.prepare('SELECT name FROM venues WHERE id = ?').get(s.owner_venue_id) : null;
    const ev = s.event_id ? db.prepare('SELECT region, slug FROM events WHERE id = ?').get(s.event_id) : null;
    const to = s.owner_venue_id ? ownerDecisionRecipients(s.owner_venue_id, s.contact_email) : (s.contact_email ? [String(s.contact_email).trim().toLowerCase()] : []);
    const evLang = s.owner_venue_id ? (db.prepare('SELECT lang FROM event_submissions WHERE id = ?').get(id) || {}).lang : null;
    if (evLang === 'fr') {
      return sendOwnerDecision(to, ownerDecisionEmail({ venueName: venue ? venue.name : 'Okanagan Roam', what: `votre événement « ${s.name} »`, outcome, reason,
        link: ev ? ownerEventUrlFr(ev) : null, owner: true, lang: 'fr' }));
    }
    return sendOwnerDecision(to, ownerDecisionEmail({ venueName: venue ? venue.name : 'Okanagan Roam', what: `your event "${s.name}"`, outcome, reason,
      link: ev ? `https://okanaganroam.com/${ev.region}/events/${ev.slug}` : null, owner: !!s.owner_venue_id }));
  }
  if (kind === 'eventchange') {
    const c = db.prepare('SELECT * FROM owner_event_changes WHERE id = ?').get(id);
    const v = c && db.prepare('SELECT name FROM venues WHERE id = ?').get(c.venue_id);
    const ev = c && db.prepare('SELECT name, region, slug FROM events WHERE id = ?').get(c.event_id);
    if (!v || !ev) return 'no_address';
    if (c.lang === 'fr') {
      return sendOwnerDecision(ownerDecisionRecipients(c.venue_id, c.contact_email), ownerDecisionEmail({ venueName: v.name, what: `la modification de votre événement « ${ev.name} »`,
        outcome, reason, edited: false, link: ownerEventUrlFr(ev), owner: true, lang: 'fr' }));
    }
    return sendOwnerDecision(ownerDecisionRecipients(c.venue_id, c.contact_email), ownerDecisionEmail({ venueName: v.name, what: `the change to your event "${ev.name}"`,
      outcome, reason, edited: false, link: `https://okanaganroam.com/${ev.region}/events/${ev.slug}`, owner: true }));
  }
  if (kind === 'venue') {
    const s = getVenueSubmission(id);
    if (!s) return 'no_address';
    const v = s.venue_id ? db.prepare('SELECT id, name, region, type, slug FROM venues WHERE id = ?').get(s.venue_id) : null;
    const message = ownerDecisionEmail({ venueName: s.name, what: 'your new listing', outcome, reason, edited: !!extra.edited, link: v ? venueListingUrl(v) : null, owner: false });
    // A new business gets its private edit link with the good news (2026-10-17): photos, hours, tours & prices or
    // menu, events and a login, all from day one. Their email goes on the link, so "Email me my link" works too.
    if (outcome === 'approved' && v) {
      const made = createOwnerLink(v.id, { contact_email: s.contact_email || undefined });
      if (made.ok) message.text = message.text.replace(/\n\nThanks,\nOkanagan Roam/, `\n\nMake your page stand out: add your photos, opening hours, ${ownerExtrasFor(v)} and events here (your private link, no password needed):\n${made.url}\n\nOn that page you can also create a login, so next time you just sign in at ${OWNER_LOGIN_URL}.\n\nThanks,\nOkanagan Roam`);
    }
    return sendOwnerDecision(s.contact_email ? [String(s.contact_email).trim().toLowerCase()] : [], message);
  }
  if (kind === 'menu') {
    const m = db.prepare('SELECT * FROM venue_menus WHERE id = ?').get(id);
    const v = m && db.prepare('SELECT id, name, region, type, slug FROM venues WHERE id = ?').get(m.venue_id);
    if (!v) return 'no_address';
    if (m.lang === 'fr') {
      const row = db.prepare('SELECT * FROM venues WHERE id = ?').get(v.id);
      const frLink = outcome === 'approved' ? `https://okanaganroam.com${venueHasFrench(row) ? menuPagePath(row, 'fr') : menuPagePath(v)}` : ownerListingUrlFr(v);
      return sendOwnerDecision(ownerDecisionRecipients(v.id, m.contact_email), ownerDecisionEmail({ venueName: v.name, what: isPriceList(v) ? frDecode(PRICE_LIST_WORDS[menuKind(v)].fr.listHtml) : 'votre menu', outcome, reason, link: frLink, owner: true, lang: 'fr' }));
    }
    const link = outcome === 'approved' ? `https://okanaganroam.com${menuPagePath(v)}` : venueListingUrl(v);
    return sendOwnerDecision(ownerDecisionRecipients(v.id, m.contact_email), ownerDecisionEmail({ venueName: v.name, what: isPriceList(v) ? `your ${PRICE_LIST_WORDS[menuKind(v)].en.list}` : 'your menu', outcome, reason, link, owner: true }));
  }
  return 'no_address';
}

// --- review actions ---------------------------------------------------------

const OWNER_EDITABLE_FIELDS = ['phone', 'website', 'description', 'name', 'address', 'menu_url', 'booking_url', 'instagram_url', 'facebook_url'];

// Applies the reviewer's edits to a pending update's text fields, checked
// exactly like the owner's own input. The owner's original is kept in
// original_changes. An edit back to what the listing already says drops that
// field. -> { ok, edited, dropped, restore } | { ok: false, errors }
function editOwnerChange(id, edits) {
  const req = getOwnerChange(id);
  if (!req || req.status !== 'pending') return { ok: true, edited: [], dropped: [] };
  const wanted = {};
  for (const f of OWNER_EDITABLE_FIELDS) {
    if (f in req.changes && typeof edits[f] === 'string' && edits[f] !== (req.changes[f] == null ? '' : String(req.changes[f]))) wanted[f] = edits[f];
  }
  if (!Object.keys(wanted).length) return { ok: true, edited: [], dropped: [] };
  const venue = db.prepare('SELECT * FROM venues WHERE id = ?').get(req.venue_id);
  if (!venue) return { ok: true, edited: [], dropped: [] };
  const { changes, errors } = validateOwnerChanges(rowToVenue(venue), venue.happy_hour_times || null, { changes: wanted });
  if (Object.keys(errors).length) return { ok: false, errors };
  const next = { ...req.changes };
  const edited = [], dropped = [];
  for (const f of Object.keys(wanted)) {
    if (f in changes) { next[f] = changes[f]; edited.push(f); } else { delete next[f]; dropped.push(f); }
  }
  const raw = db.prepare('SELECT changes, original_changes FROM owner_change_requests WHERE id = ?').get(id);
  db.prepare('UPDATE owner_change_requests SET changes = ?, original_changes = COALESCE(original_changes, ?) WHERE id = ?').run(JSON.stringify(next), raw.changes, id);
  return { ok: true, edited, dropped, restore: () => db.prepare('UPDATE owner_change_requests SET changes = ?, original_changes = ? WHERE id = ?').run(raw.changes, raw.original_changes, id) };
}

function pickEdits(edits, keys) {
  const out = {};
  if (edits && typeof edits === 'object' && !Array.isArray(edits)) for (const k of keys) if (typeof edits[k] === 'string') out[k] = edits[k];
  return out;
}

const ADMIN_REVIEW_ERRORS = {
  not_found: 'This was already removed.', not_pending: 'This was already reviewed.', venue_unavailable: 'The listing no longer exists.',
  file_missing: 'The photo file is missing.', no_fields: 'Tick at least one change to approve.', write_failed: 'Saving failed; nothing changed.',
  hours_failed: 'The hours could not be saved.', happy_hour_failed: 'The happy hour could not be saved.',
};

// One decision from the review page -> { status, body }.
async function adminReviewAction(kind, id, action, body) {
  if (action === 'dismiss' && kind !== 'photo') return { status: 400, body: { error: 'Unknown action.' } };
  if (kind === 'claim') return adminClaimAction(id, action, body, ADMIN_REVIEWER);
  const reason = typeof body.reason === 'string' ? body.reason.trim().slice(0, 300) : '';
  let r;
  if (action === 'undo') {
    // Undo a signed-in owner's instant change (2026-10-18). With a reason (portal polish, 2026-10-18) the owner gets
    // a short email in their language and sees the reason in "Your updates"; without one nobody is emailed.
    if (kind !== 'change') return { status: 400, body: { error: 'Unknown action.' } };
    const u = undoOwnerInstantChange(id, ADMIN_REVIEWER, new Date(), reason);
    if (!u.ok) {
      const msg = { not_found: 'This was already removed.', not_instant: 'Only changes that went live straight away can be undone here.', already_undone: 'This was already undone.',
        changed_since: 'Nothing to undo: every field was changed again since.', venue_unavailable: 'The listing no longer exists.' }[u.reason] || ADMIN_REVIEW_ERRORS[u.reason] || u.reason;
      return { status: u.reason === 'not_found' ? 404 : 409, body: { error: msg, detail: u.detail } };
    }
    const emailed = reason ? await notifyOwnerUndo(id, u.restored, reason) : 'not_told';
    return { status: 200, body: { ok: true, restored: u.restored, skipped: u.skipped, emailed } };
  }
  if (kind === 'change') {
    if (action === 'remove') return { status: 400, body: { error: 'Unknown action.' } };
    let fields = Array.isArray(body.fields) ? body.fields.filter((f) => typeof f === 'string') : undefined;
    let ed = { edited: [], dropped: [] };
    if (action === 'approve') {
      ed = editOwnerChange(id, pickEdits(body.edits, OWNER_EDITABLE_FIELDS));
      if (!ed.ok) return { status: 400, body: { error: Object.values(ed.errors).join(' '), errors: ed.errors } };
      if (fields) fields = fields.filter((f) => !ed.dropped.includes(f));
      if (fields && !fields.length) { if (ed.restore) ed.restore(); return { status: 400, body: { error: 'Nothing left to approve: the edits match what the listing already says.' } }; }
    }
    r = action === 'approve' ? approveOwnerChange(id, ADMIN_REVIEWER, fields) : rejectOwnerChange(id, ADMIN_REVIEWER, reason);
    if (!r.ok) {
      if (ed.restore) ed.restore();
      return { status: r.reason === 'not_found' ? 404 : r.reason === 'no_fields' ? 400 : 409, body: { error: ADMIN_REVIEW_ERRORS[r.reason] || r.reason, detail: r.detail } };
    }
    r.edited = ed.edited.length > 0;
  } else if (kind === 'photo' && action === 'dismiss') {
    r = dismissOwnerPhoto(id);
    if (!r.ok) return { status: r.reason === 'not_found' ? 404 : 409, body: { error: ADMIN_REVIEW_ERRORS[r.reason] || r.reason } };
    return { status: 200, body: { ok: true, emailed: 'not_told' } };
  } else if (kind === 'photo') {
    const credit = pickEdits(body.edits, ['credit']).credit;
    if (action === 'approve' && credit !== undefined) {
      const c = credit.trim().replace(/\s+/g, ' ');
      if (c.length < 2 || c.length > 80 || /[<>]/.test(c)) return { status: 400, body: { error: 'The credit should be 2 to 80 characters, without < or >.', errors: { credit: 'Check the credit.' } } };
      const p = db.prepare('SELECT credit, status FROM owner_photos WHERE id = ?').get(id);
      if (p && p.status === 'pending' && p.credit !== c) { db.prepare('UPDATE owner_photos SET credit = ? WHERE id = ?').run(c, id); r = { edited: true }; }
    }
    const edited = !!(r && r.edited);
    r = action === 'approve' ? approveOwnerPhoto(id, ADMIN_REVIEWER, { main: typeof body.main === 'boolean' ? body.main : undefined })
      : action === 'remove' ? removeOwnerPhoto(id, ADMIN_REVIEWER, reason) : rejectOwnerPhoto(id, ADMIN_REVIEWER, reason);
    if (!r.ok) return { status: r.reason === 'not_found' ? 404 : 409, body: { error: ADMIN_REVIEW_ERRORS[r.reason] || r.reason } };
    r.edited = edited;
  } else if (kind === 'eventchange') {
    if (action === 'remove') return { status: 400, body: { error: 'Unknown action.' } };
    r = action === 'approve' ? approveOwnerEventChange(id, ADMIN_REVIEWER) : rejectOwnerEventChange(id, ADMIN_REVIEWER, reason);
    if (!r.ok) return { status: r.reason === 'not_found' ? 404 : 409, body: { error: r.reason === 'many_dates' ? 'This event has several dates; change its dates with the admin tools.' : r.reason === 'venue_unavailable' ? 'The event was cancelled or removed.' : (ADMIN_REVIEW_ERRORS[r.reason] || r.reason), detail: r.detail } };
  } else if (kind === 'event' || kind === 'venue') {
    if (action === 'remove') return { status: 400, body: { error: 'Unknown action.' } };
    const payload = { reviewer: ADMIN_REVIEWER };
    if (action === 'reject') { if (reason) payload.reason = reason; }
    else if (kind === 'event') {
      if (Array.isArray(body.reviewed_duplicates)) payload.reviewed_duplicates = body.reviewed_duplicates.filter((n) => Number.isInteger(n) && n > 0);
      const sub = getEventSubmission(id);
      const o = pickEdits(body.edits, ['name', 'description']);
      for (const k of Object.keys(o)) if (!sub || o[k] === sub[k]) delete o[k];
      if (Object.keys(o).length) payload.overrides = o;
    } else {
      if (body.allow_duplicate === true) payload.allow_duplicate = true;
      if (body.include_amenities === true) payload.include_amenities = true;
      const sub = getVenueSubmission(id);
      const o = pickEdits(body.edits, ['name', 'description', 'address', 'phone', 'website']);
      for (const k of Object.keys(o)) if (!sub || o[k] === (sub[k] || '')) delete o[k];
      if (Object.keys(o).length) payload.overrides = o;
    }
    const out = kind === 'event'
      ? (action === 'approve' ? approveEventSubmission(id, payload) : rejectEventSubmission(id, payload))
      : (action === 'approve' ? approveVenueSubmission(id, payload) : rejectVenueSubmission(id, payload));
    if (out.status !== 200) {
      const dup = out.body.error === 'possible_duplicate' || out.body.error === 'duplicate_event';
      const errs = out.body.errors && typeof out.body.errors === 'object' ? out.body.errors : null;
      return { status: out.status, body: { error: dup ? 'This looks like an event that is already listed. Check it, then tick "Not a duplicate" to publish anyway.'
        : errs ? `Please check your edits: ${Object.values(errs).join(' ')}` : out.body.error, errors: errs || undefined, detail: out.body.detail || out.body.existing } };
    }
    r = { ok: true, edited: !!payload.overrides };
  } else if (kind === 'menu') {
    // Publishing happens in the menu editor (/admin/review/menu/<id>); here a menu is only turned down or taken off.
    if (action === 'approve') return { status: 400, body: { error: 'Open the menu editor to publish it.' } };
    if (action === 'remove') {
      const row = db.prepare("SELECT venue_id FROM venue_menus WHERE id = ? AND status = 'published'").get(id);
      if (!row) return { status: 409, body: { error: 'This menu is not live.' } };
      db.prepare("UPDATE venue_menus SET status = 'removed', rejection_reason = ?, reviewed_at = datetime('now'), reviewed_by = ?, updated_at = CURRENT_TIMESTAMP WHERE id = ?").run(reason || null, ADMIN_REVIEWER, id);
      db.prepare('UPDATE venues SET updated_at = CURRENT_TIMESTAMP WHERE id = ?').run(row.venue_id);
      r = { ok: true };
    } else {
      r = rejectMenu(id, ADMIN_REVIEWER, reason);
      if (!r.ok) return { status: 409, body: { error: ADMIN_REVIEW_ERRORS.not_pending || 'Already reviewed.' } };
    }
  } else {
    return { status: 404, body: { error: 'Unknown item.' } };
  }
  const emailed = await notifyReviewDecision(kind, id, action, { reason, applied: r.applied, edited: !!r.edited });
  return { status: 200, body: { ok: true, emailed } };
}

