function adminReviewEsc(v) { return escapeHtml(v == null ? '' : String(v)); }

// "Oct 15, 6:24 p.m." in Okanagan time.
function adminReviewTime(utc) {
  const d = new Date(`${String(utc || '').replace(' ', 'T')}Z`);
  if (Number.isNaN(d.getTime())) return String(utc || '');
  return d.toLocaleString('en-CA', { timeZone: OKANAGAN_TIME_ZONE, month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' });
}

function adminReviewActions(kind, id, opts = {}) {
  const approve = opts.remove ? '' : `<button type="button" class="rv-btn rv-approve" data-act="approve">${opts.approveLabel || 'Approve'}</button>`;
  const reject = `<button type="button" class="rv-btn rv-reject" data-act="${opts.remove ? 'remove' : 'reject'}">${opts.remove ? 'Remove from site' : 'Reject'}</button>`;
  const dismiss = opts.dismiss ? '<button type="button" class="rv-btn rv-reject" data-act="dismiss" title="Takes it off this list without emailing them">Dismiss quietly</button>' : '';
  return `<div class="rv-actions">${opts.options || ''}</div>
      <div class="rv-actions">${approve}<input type="text" name="reason" maxlength="300" placeholder="${opts.reasonPlaceholder || (opts.remove ? 'Reason (sent to the owner)' : 'Reason if rejecting (sent to them)')}">${reject}${dismiss}</div>
      ${opts.dismiss ? '<p class="rv-meta">Dismiss quietly: not published and nothing is sent to them (for photos used another way, like menu pages).</p>' : ''}
      <p class="rv-result" hidden></p>`;
}

// An editable box prefilled with the sent value; only changed boxes are sent.
function adminEditBox(key, value, opts = {}) {
  const v = adminReviewEsc(value == null ? '' : value);
  return opts.multiline
    ? `<textarea class="rv-edit" name="${key}" rows="${opts.rows || 4}" maxlength="${opts.max || 2000}" data-orig="${v}">${v}</textarea>`
    : `<input type="text" class="rv-edit" name="${key}" value="${v}" maxlength="${opts.max || 300}" data-orig="${v}">`;
}

function renderAdminChangeCard(r) {
  const rows = Object.keys(r.changes).map((f) => {
    const before = f === 'badges' ? '' : ownerValueText(f, r.previous[f]);
    const after = OWNER_EDITABLE_FIELDS.includes(f) ? adminEditBox(f, r.changes[f], { multiline: f === 'description', rows: 5, max: OWNER_DESCRIPTION_MAX + 50 })
      : adminReviewEsc(ownerValueText(f, r.changes[f]));
    return `<tr><th><label class="rv-opt"><input type="checkbox" name="field" value="${adminReviewEsc(f)}" checked>${adminReviewEsc(OWNER_FIELD_LABELS[f] || f)}</label></th>
        <td class="rv-old">${adminReviewEsc(before)}</td><td class="rv-new">${after}</td></tr>`;
  }).join('');
  return `<article class="rv-card" data-kind="change" data-id="${r.id}">
      <h3>${adminReviewEsc(r.venue_name)}</h3>
      <p class="rv-meta">Update #${r.id} · sent ${adminReviewEsc(adminReviewTime(r.submitted_at))}${r.contact_name ? ` by ${adminReviewEsc(r.contact_name)}` : ''} · <a href="${adminReviewEsc(r.listing_url)}" target="_blank" rel="noopener">listing</a></p>
      <table class="rv-diff"><tr><th>Change</th><th>Now</th><th>New</th></tr>${rows}</table>
      ${r.note ? `<p class="rv-text"><strong>Note:</strong> ${adminReviewEsc(r.note)}</p>` : ''}
      ${'address' in r.changes ? '<div class="rv-warn">New address: after approving, check the map pin on the listing (it isn\u2019t moved automatically).</div>' : ''}
      ${'name' in r.changes ? '<div class="rv-warn">New business name: the page address (URL) stays the same, so links keep working.</div>' : ''}
      ${Object.keys(r.changes).some((f) => OWNER_EDITABLE_FIELDS.includes(f)) ? '<p class="rv-meta">You can fix any text before approving.</p>' : ''}
      ${adminReviewActions('change', r.id, { approveLabel: 'Approve ticked changes' })}
    </article>`;
}

// A signed-in owner's change that went live straight away (2026-10-18): what it replaced, who, and Undo.
function renderAdminInstantCard(r) {
  const rows = Object.keys(r.changes).map((f) => {
    const before = f === 'badges' ? '' : ownerValueText(f, r.previous[f]);
    return `<tr><th>${adminReviewEsc(OWNER_FIELD_LABELS[f] || f)}</th><td class="rv-old">${adminReviewEsc(before)}</td><td class="rv-new">${adminReviewEsc(ownerValueText(f, r.changes[f]))}</td></tr>`;
  }).join('');
  // adminReviewTime ends in "p.m." already, so no second period (2026-10-18).
  const done = r.undone_at ? `<p class="rv-result">Undone ${adminReviewEsc(adminReviewTime(r.undone_at).replace(/\.$/, ''))}.${r.undo_reason ? ` Reason: ${adminReviewEsc(r.undo_reason)}` : ''}</p>` : '';
  return `<article class="rv-card${r.undone_at ? ' rv-done' : ''}" data-kind="change" data-id="${r.id}">
      <h3>${adminReviewEsc(r.venue_name)}</h3>
      <p class="rv-meta">Live change #${r.id} · ${adminReviewEsc(adminReviewTime(r.submitted_at))} by ${adminReviewEsc(String(r.reviewed_by || '').replace(/^owner:/, '') || r.contact_email || 'owner')}${r.contact_name ? ` (${adminReviewEsc(r.contact_name)})` : ''} · <a href="${adminReviewEsc(r.listing_url)}" target="_blank" rel="noopener">listing</a></p>
      <table class="rv-diff"><tr><th>Change</th><th>Before</th><th>Now</th></tr>${rows}</table>
      ${r.note ? `<p class="rv-text"><strong>Note:</strong> ${adminReviewEsc(r.note)}</p>` : ''}
      ${done || `<div class="rv-actions"><input type="text" name="reason" maxlength="300" placeholder="Reason (sent to the owner)"><button type="button" class="rv-btn rv-reject" data-act="undo">Undo</button></div><p class="rv-meta">Puts back what was there before (fields changed again since are left alone). With a reason, the owner is emailed it and sees it under Your updates; without one, they aren\u2019t emailed.</p><p class="rv-result" hidden></p>`}
    </article>`;
}

// Menus waiting for Dayton: "do it for me" requests and menus sent from a private link.
function listMenusForReview() {
  return db.prepare(`SELECT m.*, v.name AS venue_name FROM venue_menus m JOIN venues v ON v.id = m.venue_id
    WHERE m.status IN ('pending', 'help') ORDER BY m.submitted_at, m.id`).all();
}
function recentLiveMenus() {
  return db.prepare(`SELECT m.*, v.name AS venue_name FROM venue_menus m JOIN venues v ON v.id = m.venue_id
    WHERE m.status = 'published' AND m.published_at >= datetime('now', '-14 days') AND m.reviewed_by LIKE 'owner:%' ORDER BY m.published_at DESC`).all();
}
function renderAdminMenuCard(m) {
  const v = db.prepare('SELECT * FROM venues WHERE id = ?').get(m.venue_id);
  const pages = menuFiles(m.id);
  const items = menuItemCount(parseMenuData(m.data));
  const what = m.status === 'help' ? '<strong>Asked us to do it</strong>' : m.status === 'published' ? '<strong>live</strong>' : 'sent from their private link';
  const thumbs = pages.map((f, i) => (f.kind === 'pdf'
    ? `<a class="rv-btn rv-reject" href="${adminReviewEsc(f.preview)}" target="_blank" rel="noopener">PDF page ${i + 1}</a>`
    : `<a href="${adminReviewEsc(f.preview)}" target="_blank" rel="noopener"><img src="${adminReviewEsc(f.preview)}" alt="Page ${i + 1}" loading="lazy" style="height:120px;border-radius:8px;margin:0 6px 6px 0"></a>`)).join('');
  return `<article class="rv-card" data-kind="menu" data-id="${m.id}">
      <h3>${adminReviewEsc(m.venue_name)}</h3>
      <p class="rv-meta">${v ? menuNoun(v) : 'Menu'} #${m.id} · ${what} · ${menuDishCountText(items, 'en', menuKind(v))} · ${pages.length} page${pages.length === 1 ? '' : 's'} · sent ${adminReviewEsc(adminReviewTime(m.submitted_at || m.created_at))}${m.contact_email ? ` · ${adminReviewEsc(m.contact_email)}` : ''}${v ? ` · <a href="${adminReviewEsc(venueListingUrl(v))}" target="_blank" rel="noopener">listing</a>` : ''}</p>
      ${m.help_note ? `<p class="rv-text"><strong>Their note:</strong> ${adminReviewEsc(m.help_note)}</p>` : ''}
      ${thumbs ? `<div>${thumbs}</div>` : ''}
      ${m.status === 'published' ? '' : `<p><a class="rv-btn rv-approve" style="display:inline-block;text-decoration:none" href="/admin/review/menu/${m.id}">Open the menu editor</a></p>`}
      ${adminReviewActions('menu', m.id, { remove: m.status === 'published', approveLabel: '' }).replace(/<button type="button" class="rv-btn rv-approve"[^>]*>[^<]*<\/button>/, '')}
    </article>`;
}

function renderAdminPhotoCard(p, live) {
  const preview = String(p.preview_url || '').replace(/^https:\/\/okanaganroam\.com/, '');
  const main = live ? '' : `<label class="rv-opt"><input type="checkbox" name="main"${p.venue_has_own_photo ? '' : ' checked'}>Make it the main photo</label>`;
  return `<article class="rv-card" data-kind="photo" data-id="${p.id}">
      <h3>${adminReviewEsc(p.venue_name)}</h3>
      <p class="rv-meta">Photo #${p.id} · ${p.width}×${p.height} · sent ${adminReviewEsc(adminReviewTime(p.submitted_at))} · credit “${adminReviewEsc(p.credit)}”${p.is_main ? ' · <strong>main photo</strong>' : ''} · <a href="${adminReviewEsc(p.listing_url)}" target="_blank" rel="noopener">listing</a></p>
      <img class="rv-photo" src="${adminReviewEsc(preview)}" alt="" loading="lazy">
      ${live ? '' : `<label class="rv-field">Credit ${adminEditBox('credit', p.credit, { max: 80 })}</label>`}
      ${adminReviewActions('photo', p.id, { remove: live, options: main, dismiss: !live })}
    </article>`;
}

function renderAdminEventCard(s) {
  const when = `${formatSubmissionLocalDate(s.start_date)}${s.end_date && s.end_date !== s.start_date ? ` – ${formatSubmissionLocalDate(s.end_date)}` : ''}${s.all_day || !s.start_time ? '' : `, ${formatSubmissionLocalTime(s.start_time)}${s.end_time ? `–${formatSubmissionLocalTime(s.end_time)}` : ''}`}`;
  const dups = s.possible_existing_events || [];
  const dupHtml = dups.length ? `<div class="rv-warn">Possibly already listed: ${dups.map((d) => adminReviewEsc(d.name)).join(', ')}</div>` : '';
  const dupOpt = dups.length ? `<label class="rv-opt"><input type="checkbox" name="notdup" data-ids="${dups.map((d) => d.event_id).join(',')}">Not a duplicate</label>` : '';
  return `<article class="rv-card" data-kind="event" data-id="${s.id}">
      <h3>${adminReviewEsc(s.name)}</h3>
      <p class="rv-meta">Event #${s.id} · ${adminReviewEsc(when)} · ${adminReviewEsc(s.venue_name || '')}, ${adminReviewEsc(REGION_LABELS[s.region] || s.region)} · by ${adminReviewEsc(s.organizer_name)} (${adminReviewEsc(s.contact_email)})${s.owner_venue_id ? ' · <strong>from the venue owner</strong>' : ''}${s.event_url ? ` · <a href="${adminReviewEsc(s.event_url)}" target="_blank" rel="noopener nofollow">their link</a>` : ''}</p>
      ${s.partner_venue_ids && s.partner_venue_ids.length ? `<p class="rv-meta">Partner venues (the event also shows on their pages): ${adminReviewEsc(partnerVenueNamesText(s.partner_venue_ids))}</p>` : ''}
      <label class="rv-field">Name ${adminEditBox('name', s.name, { max: 120 })}</label>
      <label class="rv-field">Description ${adminEditBox('description', s.description, { multiline: true, rows: 5, max: 2000 })}</label>
      ${dupHtml}
      ${adminReviewActions('event', s.id, { options: dupOpt })}
    </article>`;
}

function adminOccText(o) {
  if (!o || !o.start_date) return '';
  const date = `${formatSubmissionLocalDate(o.start_date)}${o.end_date && o.end_date !== o.start_date ? ` – ${formatSubmissionLocalDate(o.end_date)}` : ''}`;
  return Number(o.all_day) || !o.start_time ? `${date}, all day` : `${date}, ${formatSubmissionLocalTime(o.start_time)}${o.end_time ? `–${formatSubmissionLocalTime(o.end_time)}` : ''}`;
}

function renderAdminEventChangeCard(c) {
  const ev = c.event || {}, d = c.data, now = c.occurrences[0] || {};
  const rows = [
    ['Name', ev.name, d.name],
    ['When', adminOccText(now), adminOccText(d)],
    ['Description', ev.description, d.description],
    ['Link', ev.website || '', d.event_url || ''],
    ...(Array.isArray(d.partner_venue_ids) ? [['Partners', partnerVenueNamesText(ev.id ? eventPartnerIds(ev.id) : []), partnerVenueNamesText(d.partner_venue_ids)]] : []),
  ].filter(([, a, b]) => String(a || '') !== String(b || '')).map(([label, a, b]) => `<tr><th>${label}</th><td class="rv-old">${adminReviewEsc(a)}</td><td class="rv-new">${adminReviewEsc(b)}</td></tr>`).join('');
  return `<article class="rv-card" data-kind="eventchange" data-id="${c.id}">
      <h3>${adminReviewEsc(ev.name)} <span class="rv-meta">(${adminReviewEsc(c.venue_name)})</span></h3>
      <p class="rv-meta">Event change #${c.id} · sent ${adminReviewEsc(adminReviewTime(c.submitted_at))}${ev.slug ? ` · <a href="/${adminReviewEsc(ev.region)}/events/${adminReviewEsc(ev.slug)}" target="_blank" rel="noopener">live event</a>` : ''}</p>
      ${rows ? `<table class="rv-diff"><tr><th>Change</th><th>Now</th><th>New</th></tr>${rows}</table>` : '<p class="rv-meta">Nothing visible changed (categories or notes only).</p>'}
      ${c.occurrences.length > 1 ? '<div class="rv-warn">This event has several dates; only its name, description and link can change here.</div>' : ''}
      ${adminReviewActions('eventchange', c.id, {})}
    </article>`;
}

function renderAdminVenueCard(s) {
  const dups = s.possible_existing_venues || [];
  const amen = (s.amenities || []).map((a) => (BADGE_LABELS[a] ? BADGE_LABELS[a].title : a));
  const opts = `${amen.length ? `<label class="rv-opt"><input type="checkbox" name="amenities">Publish their badges (${adminReviewEsc(amen.join(', '))})</label>` : ''}${dups.some((d) => d.blocking !== false) ? '<label class="rv-opt"><input type="checkbox" name="allowdup">Not a duplicate</label>' : ''}`;
  return `<article class="rv-card" data-kind="venue" data-id="${s.id}">
      <h3>${adminReviewEsc(s.name)}</h3>
      <p class="rv-meta">New venue #${s.id} · ${adminReviewEsc(s.type)} · ${adminReviewEsc(REGION_LABELS[s.region] || s.region)} · from ${adminReviewEsc(s.contact_name)} (${adminReviewEsc(s.contact_email)})</p>
      <label class="rv-field">Name ${adminEditBox('name', s.name, { max: 120 })}</label>
      <div class="rv-row"><label class="rv-field">Address ${adminEditBox('address', s.address)}</label><label class="rv-field">Phone ${adminEditBox('phone', s.phone, { max: 40 })}</label></div>
      <label class="rv-field">Website ${adminEditBox('website', s.website)}</label>
      <label class="rv-field">Description ${adminEditBox('description', s.description, { multiline: true, rows: 5, max: 2000 })}</label>
      ${dups.length ? `<div class="rv-warn">May already be listed: ${dups.map((d) => `${adminReviewEsc(d.name)} (same ${adminReviewEsc(d.match || 'name')}, ${adminReviewEsc(REGION_LABELS[d.region] || d.region)}${d.blocking === false ? ', check only' : ''})`).join(', ')}</div>` : ''}
      ${adminReviewActions('venue', s.id, { options: opts })}
    </article>`;
}

function recentLiveOwnerPhotos() {
  const ids = new Set(db.prepare("SELECT id FROM owner_photos WHERE status = 'approved' AND reviewed_by LIKE 'owner:%' AND submitted_at > datetime('now', '-14 days')").all().map((r) => r.id));
  return listOwnerPhotos('approved').filter((p) => ids.has(p.id));
}

// Owner sign-ups (2026-10-19, Dayton asked "how many venues are signed up"): one line at the top of /admin/review.
// A login = an owner_accounts row; a venue counts once however many logins manage it. "Sent us something" = an
// update, photo, event or menu from the venue's own link or login. Retired (redirected) listings are left out.
function ownerSignupStats(now = new Date()) {
  const one = (sql, ...a) => { try { return Number((db.prepare(sql).get(...a) || {}).n) || 0; } catch (e) { return 0; } };
  const live = 'venue_id IN (SELECT id FROM venues WHERE redirect_to IS NULL)';
  const weekAgo = new Date(now.getTime() - 7 * 86400000).toISOString().slice(0, 19).replace('T', ' ');
  const active = new Set();
  for (const sql of [`SELECT DISTINCT venue_id AS v FROM owner_change_requests WHERE ${live}`, `SELECT DISTINCT venue_id AS v FROM owner_photos WHERE ${live}`,
    'SELECT DISTINCT owner_venue_id AS v FROM event_submissions WHERE owner_venue_id IN (SELECT id FROM venues WHERE redirect_to IS NULL)',
    `SELECT DISTINCT venue_id AS v FROM venue_menus WHERE ${live}`]) {
    try { for (const r of db.prepare(sql).all()) active.add(r.v); } catch (e) { /* table missing on an old copy */ }
  }
  let list = [];
  try {
    list = db.prepare(`SELECT v.name, v.region, MIN(av.added_at) AS since, COUNT(*) AS logins FROM owner_account_venues av JOIN venues v ON v.id = av.venue_id
      WHERE v.redirect_to IS NULL GROUP BY v.id ORDER BY since DESC`).all();
  } catch (e) { list = []; }
  return {
    accounts: one('SELECT COUNT(*) AS n FROM owner_accounts'),
    newAccounts: one('SELECT COUNT(*) AS n FROM owner_accounts WHERE created_at >= ?', weekAgo),
    venuesWithLogin: list.length,
    links: one(`SELECT COUNT(*) AS n FROM venue_owner_links WHERE ${live}`),
    linksOpened: one(`SELECT COUNT(*) AS n FROM venue_owner_links WHERE last_used_at IS NOT NULL AND ${live}`),
    venuesActive: active.size,
    list,
  };
}

function renderAdminOwnerStats(st) {
  const n = (x, one, many) => `${x} ${x === 1 ? one : many}`;
  const rows = st.list.map((v) => `<li>${adminReviewEsc(v.name)} <span class="rv-meta">${adminReviewEsc(REGION_LABELS[v.region] || v.region)} · since ${adminReviewEsc(String(v.since || '').slice(0, 10))}${v.logins > 1 ? ` · ${v.logins} logins` : ''}</span></li>`).join('');
  return `<section class="rv-owners" id="owners"><h2>Owners</h2>
      <p><strong>${n(st.venuesWithLogin, 'venue has', 'venues have')} a login</strong> (${n(st.accounts, 'login', 'logins')}${st.newAccounts ? `, ${st.newAccounts} new this week` : ''}) · ${n(st.venuesActive, 'venue has', 'venues have')} sent us updates, photos, events or menus · ${st.linksOpened} of ${st.links} edit links opened</p>
      ${rows ? `<details><summary>Venues with a login</summary><ul>${rows}</ul></details>` : ''}
    </section>`;
}

function renderAdminReviewPage() {
  const changes = listOwnerChanges('pending');
  const photos = listOwnerPhotos('pending');
  const live = recentLiveOwnerPhotos();
  const events = listEventSubmissions('pending');
  const eventChanges = listOwnerEventChanges('pending');
  const venues = listVenueSubmissions('pending');
  const menus = listMenusForReview();
  const liveMenus = recentLiveMenus();
  purgeStaleVisitorContributions();
  const visitor = listVisitorContributions('pending');
  const visitorReported = listVisitorContributions('reported');
  const visitorLive = listVisitorContributions('live').filter((c) => !c.reported_count);
  const claims = listPendingClaims();
  const instant = recentInstantOwnerChanges();
  const total = changes.length + photos.length + events.length + eventChanges.length + venues.length + menus.length + visitor.length + visitorReported.length + claims.length;
  const section = (key, title, items, render, empty) => `<section class="rv-section" id="${key}"><h2>${title} <span class="rv-meta">(${items.length})</span></h2>
    ${items.length ? items.map(render).join('') : `<p class="rv-empty">${empty}</p>`}</section>`;
  const mail = ownerDirectEmail()
    ? '<p class="rv-mail">Owners get an email when you approve or reject something.</p>'
    : '<p class="rv-mail"><strong>Owner emails are off</strong> until BREVO_API_KEY is added in Railway. Owners still see the result in their business login.</p>';
  return ownerSimplePage('Review', `
    <div class="op-bar"><span><strong>Review</strong></span><button type="button" class="op-linkbtn" id="rvLogout">Sign out</button></div>
    <h1>${total ? `${total} waiting for you` : 'All caught up'}</h1>
    ${mail}
    ${renderAdminOwnerStats(ownerSignupStats())}
    <nav class="rv-tabs"><a href="#updates">Owner updates (${changes.length})</a><a href="#photos">Photos (${photos.length})</a><a href="#events">Events (${events.length})</a>${eventChanges.length ? `<a href="#eventchanges">Event changes (${eventChanges.length})</a>` : ''}<a href="#venues">New venues (${venues.length})</a><a href="#claims">Claims (${claims.length})</a><a href="#menus">Menus (${menus.length})</a><a href="#visitor">Visitor photos &amp; tips (${visitor.length})</a>${visitorReported.length ? `<a href="#visitorreported">Reported (${visitorReported.length})</a>` : ''}<a href="#live">Live photos (${live.length})</a><a href="#liveupdates">Live owner changes (${instant.length})</a></nav>
    ${section('updates', 'Owner updates', changes, renderAdminChangeCard, 'No updates waiting.')}
    ${section('photos', 'Photos to approve', photos, (p) => renderAdminPhotoCard(p, false), 'No photos waiting.')}
    ${section('events', 'Events', events, renderAdminEventCard, 'No events waiting.')}
    ${eventChanges.length ? section('eventchanges', 'Changes to live events', eventChanges, renderAdminEventChangeCard, '') : ''}
    ${section('venues', 'New venues', venues, renderAdminVenueCard, 'No new venues waiting.')}
    ${section('claims', 'Listing claims', claims, renderAdminClaimCard, 'No claims waiting.')}
    ${section('menus', 'Menus', menus, renderAdminMenuCard, 'No menus waiting.')}
    ${liveMenus.length ? section('livemenus', 'Menus owners published (last 14 days)', liveMenus, renderAdminMenuCard, '') : ''}
    ${section('visitor', 'Visitor photos &amp; tips', visitor, (c) => renderAdminVisitorCard(c, 'pending'), 'No visitor photos or tips waiting.')}
    ${visitorReported.length ? section('visitorreported', 'Reported visitor tips', visitorReported, (c) => renderAdminVisitorCard(c, 'reported'), '') : ''}
    ${visitorLive.length ? section('visitorlive', 'Visitor photos &amp; tips live (last 30 days)', visitorLive, (c) => renderAdminVisitorCard(c, 'live'), '') : ''}
    ${section('live', 'Photos owners published (last 14 days)', live, (p) => renderAdminPhotoCard(p, true), 'None in the last 14 days.')}
    ${section('liveupdates', 'Changes owners made live (last 14 days)', instant, renderAdminInstantCard, 'None in the last 14 days.')}
<script>
(function(){
  document.getElementById('rvLogout').addEventListener('click', function(){
    fetch('/admin/review/logout', { method: 'POST', credentials: 'same-origin' }).then(function(){ location.reload(); });
  });
  document.addEventListener('input', function(e){
    if (e.target.classList && e.target.classList.contains('rv-edit')) e.target.classList.toggle('rv-changed', e.target.value !== e.target.getAttribute('data-orig'));
  });
  var EMAIL = { sent: ' They were emailed.', failed: ' The email to them failed.', email_off: '', no_address: ' (No email address to tell them.)', forwarded: ' Their link went to info@okanaganroam.com to forward.', not_told: ' Nothing was sent to them.' };
  document.addEventListener('click', function(e){
    var btn = e.target.closest('button[data-act]'); if (!btn) return;
    var card = btn.closest('.rv-card'), act = btn.getAttribute('data-act'), out = card.querySelector('.rv-result');
    var reasonBox = card.querySelector('input[name=reason]'), body = { reason: reasonBox ? reasonBox.value : '' };
    var kind = card.getAttribute('data-kind');
    if (kind === 'change') body.fields = Array.prototype.map.call(card.querySelectorAll('input[name=field]:checked'), function(i){ return i.value; });
    var main = card.querySelector('input[name=main]'); if (main) body.main = main.checked;
    if (btn.hasAttribute('data-photo')) body.photo_id = Number(btn.getAttribute('data-photo'));
    var nd = card.querySelector('input[name=notdup]'); if (nd && nd.checked) body.reviewed_duplicates = nd.getAttribute('data-ids').split(',').map(Number);
    var ad = card.querySelector('input[name=allowdup]'); if (ad) body.allow_duplicate = ad.checked;
    var am = card.querySelector('input[name=amenities]'); if (am) body.include_amenities = am.checked;
    // Fix (2026-10-19): Reject acts at once and emails them, so an empty reason now asks first.
    if (act === 'reject' && !String(body.reason).trim() && !window.confirm('Reject with no reason? They will still be emailed that it was turned down.' + (kind === 'photo' ? ' To turn it down without emailing them, use Dismiss quietly.' : ''))) return;
    if (act === 'approve') {
      var edits = {}, any = false;
      Array.prototype.forEach.call(card.querySelectorAll('.rv-edit'), function(el){ if (el.value !== el.getAttribute('data-orig')) { edits[el.name] = el.value; any = true; } });
      if (any) body.edits = edits;
    }
    var buttons = card.querySelectorAll('button'); Array.prototype.forEach.call(buttons, function(b){ b.disabled = true; });
    fetch('/admin/review/' + kind + '/' + card.getAttribute('data-id') + '/' + act, { method: 'POST', credentials: 'same-origin',
      headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, body: JSON.stringify(body) })
      .then(function(r){ return r.json().then(function(j){ return { ok: r.ok, j: j }; }); })
      .then(function(x){
        out.hidden = false;
        if (x.ok) { Array.prototype.forEach.call(card.querySelectorAll('.rv-edit'), function(el){ el.disabled = true; }); out.textContent = (act === 'approve' && kind === 'claim' ? 'Approved: an edit link was made for them.' : act === 'approve' ? (body.edits ? 'Approved with your edits and live.' : 'Approved and live.') + (body.photo_id ? ' It is now the main photo.' : '') : act === 'remove' ? 'Removed from the site.' : act === 'undo' ? 'Undone: the old values are back.' + (x.j.skipped && x.j.skipped.length ? ' Left alone (changed again since): ' + x.j.skipped.join(', ') + '.' : '') : act === 'make-main' ? 'Now the main photo.' : act === 'keep' ? 'Kept on the site; reports cleared.' : act === 'dismiss' ? 'Dismissed.' : 'Rejected.') + (EMAIL[x.j.emailed] || '') + (x.j.link ? ' Their link: ' + x.j.link : ''); card.classList.add('rv-done'); return; }
        out.textContent = (x.j && x.j.error) || 'Something went wrong.';
        Array.prototype.forEach.call(buttons, function(b){ b.disabled = false; });
      })
      .catch(function(){ out.hidden = false; out.textContent = 'Could not reach the site. Check your connection.'; Array.prototype.forEach.call(buttons, function(b){ b.disabled = false; }); });
  });
})();
</script>`, `<style>${ADMIN_REVIEW_CSS}</style>`);
}

function renderAdminReviewLoginPage() {
  return ownerSimplePage('Review sign in', `
    <h1>Review</h1>
    <p>Paste the admin key (ENRICHMENT_ADMIN_TOKEN from Railway, Variables). This browser stays signed in for 30 days.</p>
    <form class="venue-form" id="rvForm" novalidate>
      <div class="form-field"><label for="rvToken">Admin key</label><input type="password" id="rvToken" autocomplete="current-password" maxlength="400"></div>
      <p class="lyv-error" id="rvError" hidden></p>
      <button type="submit" class="venue-form-submit" id="rvSubmit">Sign in</button>
    </form>
<script>
(function(){
  var f = document.getElementById('rvForm'), err = document.getElementById('rvError'), btn = document.getElementById('rvSubmit');
  f.addEventListener('submit', function(e){
    e.preventDefault(); err.hidden = true; btn.disabled = true;
    fetch('/admin/review/login', { method: 'POST', headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' }, credentials: 'same-origin',
      body: JSON.stringify({ token: document.getElementById('rvToken').value }) })
      .then(function(r){ return r.json(); })
      .then(function(j){ btn.disabled = false; if (j && j.ok) { location.reload(); return; } err.textContent = (j && j.error) || 'Please try again.'; err.hidden = false; })
      .catch(function(){ btn.disabled = false; err.textContent = 'Could not sign in. Please check your connection.'; err.hidden = false; });
  });
})();
</script>`);
}

// ---------- Owner status + photo controls (2026-10-15) ----------
// Owners see where everything they sent stands (waiting, live, not approved
// with the reason), and signed-in owners can remove their photos or pick
// the main one. Dates are shown in Okanagan time.
function ownerLocalDate(utc, fr = false) {
  const d = new Date(`${String(utc || '').replace(' ', 'T')}Z`);
  if (Number.isNaN(d.getTime())) return '';
  // "18 oct." in French (2026-10-18).
  return d.toLocaleDateString(fr ? 'fr-CA' : 'en-CA', { timeZone: OKANAGAN_TIME_ZONE, month: 'short', day: 'numeric' });
}

function ownerVenueMainImage(venueId) {
  const row = db.prepare('SELECT image_url FROM venues WHERE id = ?').get(venueId);
  return row ? row.image_url || null : null;
}

// Main photo position (2026-10-19): the height (0-100, the CSS object-position) a signed-in owner slid this photo
// to in the venue banner, or null (centred). Keyed by the path without ?v=, so a re-versioned photo keeps it.
function venuePhotoPath(imageUrl) {
  return String(imageUrl || '').split('?')[0];
}
function venuePhotoPosY(venueId, imageUrl) {
  if (!imageUrl) return null;
  const row = db.prepare('SELECT pos_y FROM venue_photo_positions WHERE venue_id = ? AND image_path = ?').get(venueId, venuePhotoPath(imageUrl));
  return row ? row.pos_y : null;
}

// Everything sent for this venue, newest first.
// French field names for "Your updates" and the instant-save message (2026-10-18).
// The badge names as the French site shows them (app.js badge.* keys).
const OWNER_BADGE_LABELS_FR = { dog_friendly: 'Accepte les chiens', vegan: 'Végane', vegetarian: 'Options végétariennes', patio: 'Terrasse', kid_friendly: 'Adapté aux enfants',
  gluten_free: 'Options sans gluten', lake_view: 'Vue sur le lac ou le vignoble', nonalcoholic: 'Options sans alcool', sports_tv: 'Sports à la télé', live_music: 'Musique en direct',
  great_groups: 'Idéal pour les groupes', happy_hour: 'Happy hour', free_entry: 'Gratuit', arts_culture: 'Arts et culture' };
const OWNER_FIELD_LABELS_FR = { hours: 'Heures', phone: 'Téléphone', website: 'Site Web', description: 'Description', badges: 'Caractéristiques', happy_hour: 'Happy hour',
  name: 'Nom de l’entreprise', address: 'Adresse', menu_url: 'Lien du menu', booking_url: 'Lien de réservation', instagram_url: 'Instagram', facebook_url: 'Facebook', open_months: 'Saison',
  price_range: 'Gamme de prix', hours_seasons: 'Heures saisonnières', closures: 'Fermetures spéciales' };
function ownerVenueActivity(venueId, limit = 12, lang = 'en') {
  const fr = lang === 'fr';
  const items = [];
  for (const r of db.prepare("SELECT * FROM owner_change_requests WHERE venue_id = ? AND status != 'superseded' ORDER BY id DESC LIMIT 10").all(venueId)) {
    let fields = [];
    try { fields = Object.keys(JSON.parse(r.changes)).map((f) => (fr ? OWNER_FIELD_LABELS_FR : OWNER_FIELD_LABELS)[f] || f); } catch (e) { /* unreadable */ }
    const what = fields.join(', ').toLowerCase().replace(/^./, (c) => c.toUpperCase());
    items.push({ kind: 'change', at: r.reviewed_at || r.submitted_at, sent: r.submitted_at, status: r.undone_at ? 'undone' : r.status, reason: r.undone_at ? r.undo_reason || null : r.rejection_reason,
      title: fr ? (fields.length ? `Mise à jour de la fiche : ${what}` : 'Mise à jour de la fiche') : fields.length ? `Listing update: ${what}` : 'Listing update' });
  }
  const today = todayLocal();
  for (const e of db.prepare('SELECT id, name, start_date, end_date, status, submitted_at, reviewed_at, reviewed_by, rejection_reason, event_id FROM event_submissions WHERE owner_venue_id = ? ORDER BY id DESC LIMIT 10').all(venueId)) {
    let status = e.status;
    const ev = e.event_id ? db.prepare('SELECT name, status FROM events WHERE id = ?').get(e.event_id) : null;
    const title = `${fr ? 'Événement : ' : 'Event: '}${ev ? ev.name : e.name}`;
    if (status === 'rejected' && e.reviewed_by === 'owner') status = 'withdrawn';
    else if (status === 'approved' && ev && ev.status === 'cancelled') status = 'cancelled';
    else if (status === 'approved' && ownerEventPendingChange(e.id)) status = 'changewait';
    const upcoming = (e.end_date || e.start_date) >= today;
    items.push({ kind: 'event', id: e.id, at: e.reviewed_at || e.submitted_at, sent: e.submitted_at, status, reason: e.rejection_reason, title, date: e.start_date,
      canEdit: upcoming && ['pending', 'approved', 'changewait'].includes(status) });
  }
  const main = ownerVenueMainImage(venueId);
  for (const ph of db.prepare("SELECT id, file, status, submitted_at, reviewed_at, reviewed_by, rejection_reason FROM owner_photos WHERE venue_id = ? AND COALESCE(reviewed_by, '') != ? ORDER BY id DESC LIMIT 20").all(venueId, OWNER_PHOTO_DISMISSED_BY)) {
    items.push({ kind: 'photo', at: ph.reviewed_at || ph.submitted_at, sent: ph.submitted_at, status: ph.reviewed_by === 'owner' && ph.status === 'rejected' ? 'removed' : ph.status,
      reason: ph.rejection_reason, title: main === `/images/owner/${ph.file}` ? (fr ? 'Photo (photo principale)' : 'Photo (main photo)') : 'Photo' });
  }
  items.sort((a, b) => String(b.sent).localeCompare(String(a.sent)));
  return items.slice(0, limit);
}

function ownerStatusLabel(item, lang = 'en') {
  const L = (en, f) => (lang === 'fr' ? f : en);
  if (item.status === 'pending') return { cls: 'wait', text: L('Waiting for review', 'En attente de vérification') };
  if (item.status === 'approved') return { cls: 'live', text: item.kind === 'event' ? L('Approved: on What’s On', 'Approuvé : à l’affiche') : L('Live', 'En ligne') };
  if (item.status === 'removed') return { cls: 'off', text: L('Removed by you', 'Retiré par vous') };
  if (item.status === 'withdrawn') return { cls: 'off', text: L('Withdrawn by you', 'Retiré par vous') };
  if (item.status === 'cancelled') return { cls: 'off', text: L('Cancelled', 'Annulé') };
  if (item.status === 'changewait') return { cls: 'wait', text: L('Change waiting for review', 'Modification en attente de vérification') };
  if (item.status === 'undone') return { cls: 'off', text: L('Changed back by us', 'Rétabli par nous') };
  return { cls: 'no', text: L('Not approved', 'Non approuvé') };
}

// Folded updates (2026-10-18): every save added a row, which pushed the form down on phones. Anything sent more than a
// day ago that isn't waiting for review now folds behind "Show all (N)"; waiting items always show, and when
// everything is old the newest row still shows.
function ownerActivityIsOld(item, now = new Date()) {
  if (item.status === 'pending' || item.status === 'changewait') return false;
  const t = new Date(`${String(item.sent || '').replace(' ', 'T')}Z`).getTime();
  return !Number.isNaN(t) && now.getTime() - t > 24 * 3600 * 1000;
}
function ownerActivityHtml(items, lang = 'en', now = new Date()) {
  if (!items.length) return '';
  const fr = lang === 'fr';
  const L = (en, f) => (fr ? f : en);
  const old = items.map((it) => ownerActivityIsOld(it, now));
  if (old.every(Boolean)) old[0] = false;
  const folded = old.filter(Boolean).length;
  return `<section class="op-activity" aria-labelledby="opActivityHead">
      <h2 id="opActivityHead" class="lyv-section-label" style="margin-top:22px">${L('Your updates', 'Vos mises à jour')}</h2>
      <ul id="opActivityList">${items.map((it, i) => {
        const st = ownerStatusLabel(it, lang);
        const why = st.cls === 'no' && it.reason ? `<span class="op-why">${escapeHtml(it.reason)}</span>`
          : it.status === 'undone' && it.reason ? `<span class="op-why">${L('Changed back by us: ', 'Rétabli par nous : ')}${escapeHtml(it.reason)}</span>` : '';
        const live = it.status !== 'pending';
        const btns = it.kind === 'event' && it.canEdit ? `<span class="op-act-btns"><button type="button" class="op-linkbtn" data-ev-change="${it.id}">${L('Change', 'Modifier')}</button> &middot; <button type="button" class="op-linkbtn" data-ev-cancel="${it.id}" data-ev-live="${live ? 1 : 0}">${live ? L('Cancel event', 'Annuler l’événement') : L('Withdraw', 'Retirer')}</button></span>` : '';
        return `<li${old[i] ? ' class="op-act-old" hidden' : ''}><span class="op-act-main"><strong>${escapeHtml(it.title)}</strong><span class="op-act-date">${L('Sent', 'Envoyé le')} ${escapeHtml(ownerLocalDate(it.sent, fr))}</span>${why}${btns}</span><span class="op-status op-status-${st.cls}">${st.text}</span></li>`;
      }).join('')}</ul>
      ${folded ? `<p class="op-hint"><button type="button" class="op-linkbtn" id="opActivityMore">${L(`Show all (${items.length})`, `Tout afficher (${items.length})`)}</button></p>
      <script>
(function(){
  var b = document.getElementById('opActivityMore'); if (!b) return;
  b.addEventListener('click', function(){
    Array.prototype.forEach.call(document.querySelectorAll('#opActivityList .op-act-old'), function(li){ li.hidden = false; });
    b.parentNode.hidden = true;
  });
})();
</script>` : ''}
    </section>`;
}

// One line per venue on "My listings".
// "Last updated" (2026-10-15): the last time the OWNER changed the listing -- the
// send date of their most recent update that went live, or of a photo of theirs
// that is live. Our own edits (research, admin tools, the review page's own
// changes) never count, so a listing no owner has touched shows no date.
// -> 'YYYY-MM-DD HH:MM:SS' (UTC) | null
function ownerLastUpdatedAt(venueId) {
  const row = db.prepare(`SELECT MAX(t) AS t FROM (
    SELECT submitted_at AS t FROM owner_change_requests WHERE venue_id = ? AND status = 'approved'
    UNION ALL SELECT submitted_at FROM owner_photos WHERE venue_id = ? AND status = 'approved')`).get(venueId, venueId);
  return (row && row.t) || null;
}

const OWNER_UPDATED_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'June', 'July', 'Aug', 'Sept', 'Oct', 'Nov', 'Dec'];
// "Sept 2, 2026" (or "2 sept. 2026" in French), in Okanagan time.
function ownerUpdatedDate(utc, fr = false) {
  const d = new Date(`${String(utc || '').replace(' ', 'T')}Z`);
  if (Number.isNaN(d.getTime())) return '';
  if (fr) return d.toLocaleDateString('fr-CA', { timeZone: OKANAGAN_TIME_ZONE, day: 'numeric', month: 'short', year: 'numeric' });
  const [y, m, day] = d.toLocaleDateString('en-CA', { timeZone: OKANAGAN_TIME_ZONE }).split('-').map(Number);
  return `${OWNER_UPDATED_MONTHS[m - 1]} ${day}, ${y}`;
}

function ownerVenueSummary(venueId, lang = 'en') {
  const fr = lang === 'fr';
  const L = (en, f) => (fr ? f : en);
  const n = (sql) => db.prepare(sql).get(venueId).n;
  const waiting = [
    [n("SELECT COUNT(*) AS n FROM owner_change_requests WHERE venue_id = ? AND status = 'pending' AND instant = 0"), L('update', 'mise à jour'), L('updates', 'mises à jour')],
    // Menus and event changes count too (2026-10-18), so the chip never says "Up to date" while one waits.
    [n("SELECT COUNT(*) AS n FROM venue_menus WHERE venue_id = ? AND status IN ('pending', 'help')"), 'menu', 'menus'],
    [n("SELECT COUNT(*) AS n FROM event_submissions WHERE owner_venue_id = ? AND status = 'pending'")
      + n("SELECT COUNT(*) AS n FROM owner_event_changes WHERE venue_id = ? AND status = 'pending'"), L('event', 'événement'), L('events', 'événements')],
    [n("SELECT COUNT(*) AS n FROM owner_photos WHERE venue_id = ? AND status = 'pending'"), 'photo', 'photos'],
  ].filter(([c]) => c > 0).map(([c, one, many]) => `${c} ${c === 1 ? one : many}`);
  const notApproved = n("SELECT COUNT(*) AS n FROM owner_change_requests WHERE venue_id = ? AND status = 'rejected' AND reviewed_at > datetime('now', '-30 days')")
    + n("SELECT COUNT(*) AS n FROM event_submissions WHERE owner_venue_id = ? AND status = 'rejected' AND reviewed_at > datetime('now', '-30 days')")
    + n(`SELECT COUNT(*) AS n FROM owner_photos WHERE venue_id = ? AND status = 'rejected' AND reviewed_by NOT IN ('owner', '${OWNER_PHOTO_DISMISSED_BY}') AND reviewed_at > datetime('now', '-30 days')`);
  const live = n("SELECT COUNT(*) AS n FROM owner_photos WHERE venue_id = ? AND status = 'approved'");
  const parts = [];
  if (waiting.length) parts.push(`<span class="op-status op-status-wait">${L('Waiting for review', 'En attente de vérification')}${fr ? ' ' : ''}: ${waiting.join(', ')}</span>`);
  if (notApproved) parts.push(`<span class="op-status op-status-no">${L(`${notApproved} not approved`, `${notApproved} non approuvé${notApproved === 1 ? '' : 's'}`)}</span>`);
  if (live) parts.push(`<span class="op-status op-status-live">${L(`${live} photo${live === 1 ? '' : 's'} live`, `${live} photo${live === 1 ? '' : 's'} en ligne`)}</span>`);
  if (n("SELECT COUNT(*) AS n FROM venue_menus WHERE venue_id = ? AND status = 'published'")) {
    const v = db.prepare('SELECT * FROM venues WHERE id = ?').get(venueId);
    parts.push(`<span class="op-status op-status-live">${v && PRICE_LIST_WORDS[menuKind(v)] ? L('Prices live', 'Prix en ligne') : L('Menu live', 'Menu en ligne')}</span>`);
  }
  const last = ownerLastUpdatedAt(venueId);
  const lastHtml = last ? `<br><span class="op-last">${L('Last updated', 'Dernière mise à jour :')} ${ownerUpdatedDate(last, fr)}</span>` : '';
  return (parts.length ? parts.join(' ') : `<span class="op-status op-status-live">${L('Up to date', 'À jour')}</span>`) + lastHtml;
}

// POST /owner/account/venue/<id>/photos/<photoId>/(remove|main|up|down), signed-in owners only.
async function handleOwnerPhotoAction(req, res, account, venueId, photoId, action) {
  if (!isSameOriginSubmission(req)) return sendSubmissionResponse(res, 403, { ok: false, error: 'Please use the Okanagan Roam website.' });
  if (!account) return sendSubmissionResponse(res, 401, { ok: false, error: 'Please sign in again at okanaganroam.com/owner/login.' });
  const found = venueForOwnerAccount(account, venueId);
  const photo = found && db.prepare('SELECT * FROM owner_photos WHERE id = ? AND venue_id = ?').get(photoId, venueId);
  if (!photo || photo.status === 'rejected') return sendSubmissionResponse(res, 404, { ok: false, error: 'That photo isn’t available any more.' });
  if (action === 'up' || action === 'down') {
    const r = moveOwnerPhoto(venueId, photo.id, action === 'up' ? -1 : 1);
    if (!r.ok) return sendSubmissionResponse(res, 409, { ok: false, error: 'The main photo always comes first. Make another photo main to change it.' });
    return sendSubmissionResponse(res, 200, { ok: true, order: r.order, moved: r.moved, position: r.position || null, total: r.total || r.order.length });
  }
  if (action === 'main') {
    if (photo.status !== 'approved') return sendSubmissionResponse(res, 409, { ok: false, error: 'This photo is still waiting for review.' });
    // The old main photo stays near the front (2026-10-18): it becomes the first of the other photos, and the rest
    // keep their order. It used to drop to the end of the gallery (it had no place in the order, being main).
    const mainBefore = ownerVenueMainImage(venueId);
    const others = ownerPhotosForVenue(venueId).filter((p) => p.id !== photo.id && mainBefore !== `/images/owner/${p.file}`);
    const oldMain = ownerPhotosForVenue(venueId).find((p) => p.id !== photo.id && mainBefore === `/images/owner/${p.file}`);
    const r = approveOwnerPhoto(photo.id, 'owner', { main: true });
    if (r.ok && oldMain) {
      const set = db.prepare('UPDATE owner_photos SET sort_order = ? WHERE id = ?');
      [oldMain, ...others].forEach((p, n) => set.run(n + 1, p.id));
    }
    return sendSubmissionResponse(res, r.ok ? 200 : 409, r.ok ? { ok: true, main: true } : { ok: false, error: 'Sorry, that didn’t work. Please try again.' });
  }
  const r = removeOwnerPhoto(photo.id, 'owner', 'removed by owner');
  if (!r.ok) return sendSubmissionResponse(res, 409, { ok: false, error: 'Sorry, that didn’t work. Please try again.' });
  // Removing the main photo hands the spot to the owner's newest other live photo.
  let newMain = null;
  if (r.was_main) {
    const next = db.prepare("SELECT id FROM owner_photos WHERE venue_id = ? AND status = 'approved' ORDER BY id DESC LIMIT 1").get(venueId);
    if (next && approveOwnerPhoto(next.id, 'owner', { main: true }).ok) newMain = next.id;
  }
  return sendSubmissionResponse(res, 200, { ok: true, removed: true, new_main: newMain });
}

// POST /owner/account/venue/<id>/photo-position {y: 0-100}, signed-in owners only (2026-10-19): where the main photo
// sits in the venue banner. Saved for the photo that is main right now; 50 (centred) removes the row.
async function handleOwnerPhotoPosition(req, res, account, venueId) {
  if (!isSameOriginSubmission(req)) return sendSubmissionResponse(res, 403, { ok: false, error: 'Please use the Okanagan Roam website.' });
  if (!account) return sendSubmissionResponse(res, 401, { ok: false, error: 'Please sign in again at okanaganroam.com/owner/login.' });
  const found = venueForOwnerAccount(account, venueId);
  if (!found) return sendSubmissionResponse(res, 404, { ok: false, error: 'That listing isn’t available any more.' });
  let body;
  try { body = await readLimitedJsonBody(req, 1024); } catch (err) { body = null; }
  const y = body && typeof body === 'object' ? Number(body.y) : NaN;
  if (!Number.isFinite(y) || y < 0 || y > 100) return sendSubmissionResponse(res, 400, { ok: false, error: 'Sorry, that didn’t work. Please try again.' });
  const main = ownerVenueMainImage(venueId);
  if (!main || !/^(?:https:\/\/|\/images\/)/.test(main)) return sendSubmissionResponse(res, 409, { ok: false, error: 'Your page doesn’t have a main photo yet.' });
  const pos = Math.round(y);
  const before = venuePhotoPosY(venueId, main);
  if (pos === 50) db.prepare('DELETE FROM venue_photo_positions WHERE venue_id = ? AND image_path = ?').run(venueId, venuePhotoPath(main));
  else {
    db.prepare(`INSERT INTO venue_photo_positions (venue_id, image_path, pos_y, updated_by) VALUES (?, ?, ?, ?)
      ON CONFLICT (venue_id, image_path) DO UPDATE SET pos_y = excluded.pos_y, updated_at = CURRENT_TIMESTAMP, updated_by = excluded.updated_by`)
      .run(venueId, venuePhotoPath(main), pos, `owner:${account.email}`);
  }
  if (before !== (pos === 50 ? null : pos)) {
    db.prepare(`INSERT INTO venue_enrichment_log (venue_id, field_name, old_value, new_value, source, source_ref, confidence, batch_id, auto_accepted, reviewed_by)
      VALUES (?, 'image_position', ?, ?, 'venue_owner', ?, 'high', NULL, 1, ?)`)
      .run(venueId, before === null ? null : String(before), pos === 50 ? null : String(pos), venuePhotoPath(main), `owner:${account.email}`);
  }
  return sendSubmissionResponse(res, 200, { ok: true, y: pos });
}

